INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5548', 'spa', 'ungir — consagrar o comisionar mediante la aplicación de aceite, significando designación divina', 'χρίω es el verbo del que deriva Χριστός (‘el Ungido’), y cada aparición en el Nuevo Testamento conlleva una fuerte carga teológica. Aparece cinco veces, siempre refiriéndose al acto de Dios de ungir: Jesús lee la declaración de Isaías ‘el Espíritu del Señor me ha ungido’ en la sinagoga de Nazaret (Lc 4:18); la iglesia primitiva confiesa que Dios ungió a Jesús de Nazaret con el Espíritu Santo (Hch 4:27; 10:38); Pablo habla de Dios ungiendo a los creyentes en Cristo (2 Co 1:21); y Hebreos cita el Salmo 45: ‘te ungió Dios con óleo de alegría’ (He 1:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5549', 'spa', 'tardar, demorar, demorarse — ser lento en llegar o detenerse más de lo esperado', 'χρονίζω significa tardar, demorar o detenerse, derivado de χρόνος (‘tiempo’). En el Nuevo Testamento aparece exclusivamente en contextos de llegada anticipada y la ansiedad o complacencia que la espera produce. El siervo malvado dice ‘mi señor tarda’ y comienza a maltratar a sus consiervos (Mt 24:48; Lc 12:45). Las vírgenes insensatas se duermen porque el novio ‘tarda’ (Mt 25:5). El pueblo se extraña de la demora de Zacarías en el templo (Lc 1:21). Y Hebreos cita a Habacuc: ‘el que ha de venir vendrá y no tardará’ (He 10:37). El español ‘tardar’ comparte la misma raíz latina (tardare), capturando bien la tensión escatológica del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5550', 'spa', 'Tiempo, período, duración — un lapso mensurable, a diferencia del momento decisivo (καιρός)', 'Χρόνος designa el tiempo como extensión cuantificable o duración transcurrida, en silencioso contraste con καιρός, que marca el momento oportuno o decisivo. En sus 54 apariciones neotestamentarias mide períodos de espera («mucho tiempo después», Mt 25:19), lapsos transcurridos («¿cuánto tiempo hace que le sucede esto?», Mc 9:21) y eras de ignorancia ahora concluidas (Hch 17:30). El interrogatorio de Herodes a los magos sobre el χρόνος exacto de la aparición de la estrella (Mt 2:7, 16) muestra la afinidad de la palabra con intervalos datables y calculables. Las traducciones son llamativamente uniformes: el español «tiempo» capta con precisión este sentido neutro y mensurable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5552', 'spa', 'De oro, hecho de oro — adjetivo que describe objetos fabricados con oro o recubiertos de oro. Χρύσεος (contraído χρυσοῦς) es el adjetivo que significa', 'De oro, hecho de oro — adjetivo que describe objetos fabricados con oro o recubiertos de oro. Χρύσεος (contraído χρυσοῦς) es el adjetivo que significa ''de oro'' o ''hecho de oro'', derivado de χρυσός (''oro''). Sus 18 ocurrencias en el Nuevo Testamento se agrupan abrumadoramente en dos contextos: la descripción del mobiliario del tabernáculo en Hebreos y la imaginería visionaria de Apocalipsis. En He 9:4, el autor cataloga el altar de oro del incienso y el arca del pacto recubierta de oro, que contenía la urna de oro con el maná — tres usos en un solo versículo que evocan el esplendor del espacio más sagrado de Israel. Apocalipsis despliega el adjetivo profusamente para el templo celestial y su contenido: candeleros de oro (Ap 1:12, 20; 2:1), un cinto de oro sobre el Hijo del Hombre (Ap 1:13), coronas de oro sobre los ancianos (Ap 4:4), copas de oro llenas de incienso (Ap 5:8; 15:7), un altar de oro ante el trono (Ap 8:3), incensarios de oro (Ap 8:3), y una caña de medir de oro (Ap 21:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5553', 'spa', 'χρυσίον — oro; el metal precioso, ya sea en bruto, refinado o labrado en objetos. El sustantivo neutro χρυσίον (''oro'') es un diminutivo de χρυσός pero', 'χρυσίον — oro; el metal precioso, ya sea en bruto, refinado o labrado en objetos. El sustantivo neutro χρυσίον (''oro'') es un diminutivo de χρυσός pero funciona sin fuerza diminutiva en el griego koiné, denotando oro en todas sus formas — metal en bruto, sustancia refinada, monedas y objetos elaborados. Pedro declara al cojo: ''No tengo plata ni oro'' (Hechos 3:6), usando χρυσίον para la riqueza material. Más adelante, Pedro compara la fe probada por fuego con el oro que perece a pesar de ser refinado (1 Pedro 1:7). Apocalipsis lo emplea para coronas doradas, copas y el adorno de Babilonia (Apocalipsis 17:4; 18:16). La palabra también aparece en exhortaciones sobre el adorno modesto (1 Pedro 3:3) y el valor relativo del tesoro espiritual sobre el material.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5557', 'spa', 'Oro -- el metal precioso, ya sea como sustancia material, medio de intercambio o simbolo de valor supremo. El sustantivo χρυσός (chrysos) se refiere a', 'Oro -- el metal precioso, ya sea como sustancia material, medio de intercambio o simbolo de valor supremo. El sustantivo χρυσός (chrysos) se refiere al oro como metal precioso en sus diversos usos antiguos: como material para objetos sagrados, como medio de cambio y como medida de valor supremo. Los magos traen oro al nino Jesus (Mt 2:11), ubicandolo en primer lugar entre sus regalos. Jesus prohibe a los Doce llevar oro en su mision (Mt 10:9). La casuistica farisaica sobre juramentos por el oro del templo queda al descubierto como absurda (Mt 23:16-17). Pedro declara que los creyentes fueron redimidos no con cosas perecederas como el oro y la plata, sino con la sangre preciosa de Cristo (1 P 1:18). Santiago 5:3 advierte que el oro atesorado se corroera como testimonio contra los avaros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5560', 'spa', 'Cojo, lisiado — persona con discapacidad física en las piernas o los pies, incapaz de caminar con normalidad. En los Evangelios, χωλός aparece de mane', 'Cojo, lisiado — persona con discapacidad física en las piernas o los pies, incapaz de caminar con normalidad. En los Evangelios, χωλός aparece de manera prominente en el ministerio sanador de Jesús: los cojos andan junto con los ciegos que ven y los sordos que oyen (Mt 11:5; 15:31), y las multitudes traen cojos a Jesús en el templo (Mt 21:14). La palabra también tiene fuerza contundente en la advertencia de Jesús de que es mejor entrar en la vida cojo que ser arrojado entero a la Gehena (Mt 18:8; Mc 9:45). En Hechos, la sanación del hombre cojo de nacimiento en la Puerta Hermosa (Hch 3:2; 14:8) se convierte en una señal emblemática de la autoridad apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5561', 'spa', 'región, país o tierra abierta; un espacio definido por la geografía, el cultivo o la posesión territorial', 'región, país o tierra abierta; un espacio definido por la geografía, el cultivo o la posesión territorial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5562', 'spa', 'Tener capacidad para, contener; aceptar o recibir (mental o espiritualmente); ir, moverse, avanzar. Verbo griego versatil cuya imagen central es la ca', 'Tener capacidad para, contener; aceptar o recibir (mental o espiritualmente); ir, moverse, avanzar. Verbo griego versatil cuya imagen central es la capacidad espacial, ya sea que un recipiente contenga agua o un lugar albergue personas. De la contencion fisica (Jn 2:6, las tinajas de piedra que ''contenian'' de veinte a treinta galones cada una), el significado se extiende a la recepcion intelectual y espiritual: puede tu corazon dar cabida a una ensenanza dificil? (Mt 19:11-12). Pablo apela con la misma metafora en 2 Co 7:2: ''Hacednos lugar''. Un tercer sentido, mas antiguo, de movimiento fisico -- ir o avanzar -- aparece cuando Jesus pregunta adonde ''va'' la comida (Mt 15:17) y cuando Pedro dice que el Senor es paciente, no queriendo que ninguno perezca sino que todos ''lleguen'' al arrepentimiento (2 P 3:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5563', 'spa', 'Separar, dividir; partir o irse (especialmente en contexto matrimonial); apartar, designar. A partir de la raíz χωρίς (''aparte''), este verbo abarca ta', 'Separar, dividir; partir o irse (especialmente en contexto matrimonial); apartar, designar. A partir de la raíz χωρίς (''aparte''), este verbo abarca tanto la acción de desunir como el estado resultante de estar separado. La declaración solemne de Jesús «lo que Dios unió, no lo separe el hombre» (Mt 19:6; Mc 10:9) emplea la fuerza transitiva, mientras que las instrucciones de Pablo sobre el matrimonio usan el sentido intransitivo de un cónyuge que «se aparta» (1 Co 7:10-11, 15). En Romanos 8:35, 39, Pablo pregunta triunfalmente qué podrá «separarnos del amor de Cristo» — nada en toda la creación. El término adquiere un giro teológico distintivo en Hebreos 7:26, donde Cristo nuestro sumo sacerdote es descrito como «apartado de los pecadores».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5564', 'spa', 'Un lugar, terreno o propiedad; abarca desde una localidad con nombre propio hasta una parcela que puede comprarse o venderse. Diminutivo de χώρα (''reg', 'Un lugar, terreno o propiedad; abarca desde una localidad con nombre propio hasta una parcela que puede comprarse o venderse. Diminutivo de χώρα (''región, país'') que en la práctica no conserva fuerza diminutiva, y designa desde un punto geográfico con nombre hasta una finca considerable. En los relatos de la Pasión, Getsemaní y Gólgota reciben cada uno el nombre de χωρίον —''un lugar llamado Getsemaní'' (Mt 26:36; Mr 14:32)— subrayando la localidad en sí. En Hechos, el mismo vocablo se orienta decididamente hacia la propiedad: el ''Campo de Sangre'' de Judas (Hch 1:18–19), el terreno de Ananías y Safira (Hch 5:3, 8) y las posesiones vendidas por los primeros creyentes (Hch 4:34). En español esta distinción se refleja con precisión: ''lugar'' para el sentido geográfico frente a ''campo/terreno'' para el sentido de propiedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5565', 'spa', 'Sin, aparte de, además de — preposición con genitivo que expresa separación, exclusión o independencia', 'Sin, aparte de, además de — preposición con genitivo que expresa separación, exclusión o independencia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5567', 'spa', 'cantar alabanzas, hacer música — alabar a Dios con la voz o con instrumento de cuerdas', 'ψάλλω significaba originalmente pulsar o tañer una cuerda, y por extensión tocar un instrumento de cuerdas y cantar con su acompañamiento. En la Septuaginta traduce de forma constante el hebreo זָמַר (''hacer música en alabanza''). En tiempos del Nuevo Testamento el énfasis se ha desplazado hacia la alabanza vocal, aunque la resonancia instrumental nunca desaparece del todo. Pablo lo empareja con ''cantar'' en Efesios 5:19 y se compromete a cantar alabanzas tanto con el espíritu como con el entendimiento (1 Co 14:15). Santiago pregunta si alguien está alegre y le indica que ''cante salmos'' (Stg 5:13). El sentido central es la adoración musical dirigida a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5568', 'spa', 'Salmo; canto sagrado originalmente entonado con acompañamiento de cuerdas, usado para los Salmos del AT y cánticos de adoración.', 'El griego ψαλμός se refería originalmente al rasgueo de un instrumento de cuerdas y pasó a designar un canto entonado con tal acompañamiento. En el Nuevo Testamento cumple una doble función: nombra el libro bíblico de los Salmos cuando Jesús y los apóstoles citan las Escrituras (Lucas 20:42; Hechos 1:20; Hechos 13:33), y describe un cántico espontáneo de adoración ofrecido durante una reunión cristiana (1 Corintios 14:26). El español ''salmo'' y el francés ''psaume'' son descendientes directos de este término griego, preservando el vínculo entre la ejecución musical y el texto sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5571', 'spa', 'Falso, mentiroso, engañoso; que se caracteriza por la falsedad o el engaño deliberado', 'Este adjetivo describe lo que es falso o se caracteriza por la mentira, en oposición directa a lo verdadero (ἀληθής). En Hechos 6:13, testigos falsos declaran contra Esteban con acusaciones inventadas. Apocalipsis 2:2 elogia a la iglesia de Éfeso por poner a prueba a quienes se dicen apóstoles y descubrir que son mentirosos. En Apocalipsis 21:8, «todos los mentirosos» figuran entre los excluidos de la nueva Jerusalén. La palabra conlleva un peso moral fuerte: la falsedad no es simple error, sino engaño intencional. En el griego clásico se usaba tanto en la lógica, para las falacias, como en la ética, para las acusaciones falsas y los testimonios fraudulentos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5574', 'spa', 'pseudomai — mentir, hablar falsamente; hacer una declaración deliberadamente falsa o actuar de manera engañosa. El verbo deponente medio/pasivo ψεύδομ', 'pseudomai — mentir, hablar falsamente; hacer una declaración deliberadamente falsa o actuar de manera engañosa. El verbo deponente medio/pasivo ψεύδομαι (''mentir, hablar falsamente'') denota el acto de falsedad deliberada, ya sea de palabra o de conducta. Sus apariciones en el Nuevo Testamento abarcan varios registros: juramentos solemnes de veracidad (''no miento'', Ro 9:1; 2 Co 11:31; Gá 1:20; 1 Ti 2:7), mandatos éticos (''no os mintáis los unos a los otros'', Col 3:9), el relato de Ananías mintiendo al Espíritu Santo (Hch 5:3-4), la afirmación teológica de que Dios no puede mentir (He 6:18) y la bienaventuranza de Jesús sobre quienes «digan toda clase de mal contra vosotros, mintiendo» (Mt 5:11). La traducción uniforme en los distintos idiomas — español mentir, francés mentir, alemán lügen, árabe kadhaba — confirma un único sentido central de falsedad intencional sin subdivisión semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5576', 'spa', 'dar falso testimonio, levantar falso testimonio — testificar falsamente contra alguien', 'ψευδομαρτυρέω es un compuesto de ψεῦδος (''falsedad'') y μαρτυρέω (''testificar''), y aparece en el Nuevo Testamento exclusivamente en relación con el noveno mandamiento y su transgresión. Jesús cita ''no darás falso testimonio'' como parte del resumen del Decálogo en sus encuentros con el joven rico (Mt 19:18; Mr 10:19; Lc 18:20). Marcos muestra luego el mandamiento siendo quebrantado en tiempo real cuando los testigos en el juicio de Jesús ''daban falso testimonio contra él'' (Mr 14:56-57). La expresión española ''dar falso testimonio'' traduce el compuesto de manera literal, conservando su gravedad jurídica y covenantal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5578', 'spa', 'Falso profeta — quien reclama fraudulentamente tener revelación divina, engañando al pueblo de Dios con mensajes falsificados. El sustantivo compuesto', 'Falso profeta — quien reclama fraudulentamente tener revelación divina, engañando al pueblo de Dios con mensajes falsificados. El sustantivo compuesto ψευδοπροφήτης (pseudoprophētēs) designa a alguien que afirma falsamente hablar en nombre de Dios. Jesús advierte que vienen como lobos con piel de oveja (Mt 7:15) y predice su proliferación en los últimos tiempos con señales engañosas (Mt 24:11, 24; Mr 13:22). El hechicero Barjesús es llamado falso profeta (Hch 13:6). Juan ordena probar los espíritus porque ''muchos falsos profetas han salido por el mundo'' (1 Jn 4:1). Apocalipsis personifica al falso profeta supremo como el propagandista de la bestia (Ap 16:13; 19:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5579', 'spa', 'Mentira, falsedad — una desviación deliberada de la realidad, opuesta a la verdad de Dios. El sustantivo ψεῦδος (pseudos) significa ''mentira'' o ''false', 'Mentira, falsedad — una desviación deliberada de la realidad, opuesta a la verdad de Dios. El sustantivo ψεῦδος (pseudos) significa ''mentira'' o ''falsedad'', y denota un apartamiento deliberado de la verdad. En Juan 8:44, Jesús identifica al diablo como aquel que habla ''de su propia mentira'' — la falsedad es el lenguaje nativo de Satanás. Pablo declara que la humanidad ''cambió la verdad de Dios por la mentira'' (Ro 1:25), haciendo de ψεῦδος la marca definitoria de la idolatría. En Efesios 4:25, se exhorta a los creyentes a ''desechar la mentira'' y hablar verdad los unos con los otros. La dimensión escatológica emerge en 2 Tesalonicenses 2:9-11, donde el inicuo opera con ''prodigios mentirosos'' y Dios envía ''un poder engañoso para que crean la mentira''. La visión final de Apocalipsis excluye a todo el que ''ama y practica la mentira'' (Ap 22:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5583', 'spa', 'Mentiroso — el que habla falsedad; aplicado al diablo, a los seres humanos e incluso hipotéticamente a Dios. El sustantivo ψεύστης (pseustēs) signific', 'Mentiroso — el que habla falsedad; aplicado al diablo, a los seres humanos e incluso hipotéticamente a Dios. El sustantivo ψεύστης (pseustēs) significa ''mentiroso'', aquel que habitual o característicamente dice lo que es falso. Jesús llama al diablo ''mentiroso y padre de la mentira'' (Jn 8:44), estableciendo a Satanás como el mentiroso arquetípico. En el mismo discurso, Jesús advierte que cualquiera que niegue conocer a Dios ''es mentiroso'' (Jn 8:55). Pablo cita la máxima provocadora ''sea Dios veraz y todo hombre mentiroso'' (Ro 3:4). Las epístolas juaninas desarrollan el concepto: quien dice conocer a Dios pero desobedece ''es mentiroso'' (1 Jn 1:10; 2:4, 22; 4:20; 5:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5584', 'spa', 'Palpar, tocar, tantear; manejar algo físicamente o buscar a tientas en la oscuridad.', 'Verbo que significa tocar, palpar o tantear en busca de algo, generalmente implicando una exploración táctil más que visual. En Lucas 24:39, el Cristo resucitado invita a sus discípulos a palparlo para verificar su realidad corporal. Primera de Juan 1:1 retoma esta imagen con manos que han palpado al Verbo de vida. Hechos 17:27 lo emplea en sentido figurado para describir a la humanidad buscando a Dios a tientas en la oscuridad espiritual. Hebreos 12:18 contrasta el Sinaí — un monte tangible — con la Jerusalén celestial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5586', 'spa', 'Piedrecita, guijarro; usado para votar o como ficha; también piedra preciosa', 'Este sustantivo designa una piedra pequeña y lisa que en la antigua Grecia cumplía funciones prácticas como contar, votar o jugar. En Hechos 26:10, Pablo dice que «dio su voto» (literalmente «echó su piedrecita») contra los cristianos, evocando la imagen de las piedras de votación depositadas en urnas. En Apocalipsis 2:17, Cristo promete al vencedor «una piedrecita blanca, y en ella un nombre nuevo escrito», imagen que posiblemente alude a la absolución judicial, la admisión al banquete mesiánico o una señal de conocimiento íntimo. La piedra blanca podría evocar los votos del jurado, donde el blanco significaba absolución y el negro, condena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5590', 'spa', 'Alma, ser interior, vida; principio vital de la persona que abarca identidad espiritual, deseos y existencia mortal.', 'ψυχή es uno de los vocablos antropológicos más ricos del Nuevo Testamento, cuyo espectro semántico se extiende desde la vida física hasta la interioridad más profunda de la persona. Jesús enseña que se puede perder la propia ψυχή y a la vez salvarla (Mt 16:25), jugando simultáneamente con la dimensión corporal y la espiritual. El término traduce el hebreo נֶפֶשׁ en toda la Septuaginta, heredando la misma amplitud de significado. En la mayoría de sus 103 apariciones neotestamentarias, ψυχή designa el yo interior como sede de emociones, voluntad e identidad espiritual, más que la mera existencia biológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5591', 'spa', 'Natural, anímico, no espiritual; relativo al principio de vida natural (ψυχή) en contraste con el Espíritu (πνευμα).', 'Ψυχικός deriva de ψυχή («alma, vida natural») y marca un límite crucial en la teología paulina y epistolar. La persona «natural» de 1 Cor 2:14 no puede recibir las cosas del Espíritu porque se disciernen espiritualmente. En 1 Cor 15:44-46, Pablo distingue entre el cuerpo ψυχικόν (sembrado en debilidad) y el cuerpo πνευματικόν (resucitado en poder). Jas 3:15 califica la sabiduría mundana como «terrenal, ψυχική, demoníaca». Las traducciones revelan matices: el español alterna entre «natural» y «anímico», el francés entre «naturel» y «charnel», y el alemán entre «natürlich» y «seelisch», captando cada uno una faceta diferente de este término rico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5592', 'spa', 'Frío; frialdad, clima invernal, temperatura baja', 'Este sustantivo denota el frío, ya sea como condición física o como clima helado. En Juan 18:18, los siervos y guardias se calentaban junto a una fogata de carbón «porque hacía frío» durante el juicio de Jesús. Hechos 28:2 describe «la lluvia y el frío» que motivaron a los habitantes de Malta a encender un fuego para el grupo náufrago de Pablo. En 2 Corintios 11:27, Pablo enumera «el frío y la desnudez» entre las penalidades de su ministerio apostólico: la exposición a la intemperie sin ropa ni refugio adecuados. La palabra subraya la incomodidad y el peligro de las condiciones gélidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5593', 'spa', 'Frío; literalmente de temperatura, figuradamente de apatía o tibieza espiritual.', 'Adjetivo que significa frío en temperatura, usado tanto en sentido literal como en una vívida metáfora de la condición espiritual. En Mateo 10:42, Jesús promete recompensa a quien dé un vaso de agua fría a un pequeño, un sencillo acto de bondad refrescante. En Apocalipsis 3:15-16, el Cristo glorificado se dirige a Laodicea con las célebres palabras: «no eres ni frío ni caliente». Aquí, paradójicamente, ser frío sería preferible al tibio término medio, pues incluso la frialdad total posee una honestidad contundente de la que la tibieza carece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5596', 'spa', 'Bocado o trozo pequeño de pan, especialmente uno mojado y ofrecido a otro durante una comida.', 'Derivado del griego ψωμός (un bocado o mordisco), esta forma diminutiva designa un pequeño trozo de pan. En el Nuevo Testamento aparece exclusivamente en el relato de la Última Cena de Juan 13, donde Jesús moja un bocado y se lo ofrece a Judas Iscariote. Compartir un bocado tenía un profundo significado en las costumbres orientales de la mesa, lo que hace la traición aún más desgarradora. El término español «bocado» conserva con precisión la intimidad del gesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5598', 'spa', 'Omega, última letra del alfabeto griego, usada como título divino que expresa finalidad absoluta y plenitud.', 'La vigésimo cuarta y última letra del alfabeto griego, omega posee un peso simbólico que trasciende con creces su valor fonético. En el Apocalipsis, Dios y Cristo se declaran «el Alfa y la Omega» — el principio y el fin — empleando los límites del alfabeto como metáfora de soberanía absoluta sobre todo el tiempo y la creación. El término aparece cuatro veces, siempre emparejado con Alfa, formando un merismo que abarca todo, desde lo primero hasta lo último. Las traducciones en todas las lenguas conservan la forma transliterada «Omega», preservando su carácter icónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5599', 'spa', '¡Oh! Partícula exclamativa vocativa usada para dirigirse directamente a alguien, frecuentemente con fuerte emoción. Esta exclamación monosilábica sirv', '¡Oh! Partícula exclamativa vocativa usada para dirigirse directamente a alguien, frecuentemente con fuerte emoción. Esta exclamación monosilábica sirve como partícula vocativa de interpelación directa, generalmente cargada de emoción. En los Evangelios, Jesús la usa al lamentar la falta de fe — ''¡Oh generación incrédula!'' (Mt 17:17; Mc 9:19; Lc 9:41) — y al elogiar una fe sorprendente — ''¡Oh mujer, grande es tu fe!'' (Mt 15:28). Pablo la emplea tanto en reprensión como en argumentación apasionada (Ro 2:1, 3; Gá 3:1; 1 Ti 6:11). En el camino a Emaús, el Cristo resucitado reprende suavemente: ''¡Oh insensatos, y tardos de corazón para creer!'' (Lc 24:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5600', 'spa', 'presente de subjuntivo de ''ser/estar''; que sea, que esté, pudiera ser', 'Esta forma del verbo griego fundamental ''ser/estar'' expresa posibilidad, potencialidad o contingencia en lugar de un hecho simple. Aparece en oraciones condicionales, cláusulas de propósito y expresiones de deseo o exhortación. Donde el indicativo afirma lo que es, el subjuntivo considera lo que podría ser o debería ser. El griego emplea este modo con mucha mayor frecuencia que el español moderno, lo que lo hace esencial para expresar duda, propósito y situaciones hipotéticas a lo largo del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5601', 'spa', 'Obed; antepasado en la línea mesiánica, hijo de Booz y Rut, abuelo de David', 'Este nombre propio designa a Obed, hijo de Booz y Rut, y abuelo del rey David. Aparece en las genealogías de Jesús en Mateo 1:5 (dos veces) y Lucas 3:32, estableciendo el derecho legal de Jesús al trono davídico. El nacimiento de Obed se narra en Rut 4, donde las mujeres de Belén lo celebran como aquel que renovará la vida de Noemí y la sostendrá en su vejez. Su madre Rut, siendo moabita, se convierte en antepasada del Mesías, una hermosa ilustración de la gracia que trasciende las fronteras étnicas. El nombre mismo podría significar «siervo» o «adorador».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5602', 'spa', 'ὧδε — aquí, en este lugar; adverbio demostrativo de ubicación que señala la proximidad del hablante', 'El adverbio ὧδε («aquí») es un locativo demostrativo que señala la ubicación inmediata del hablante o un lugar presente en el contexto del discurso. En sus 62 apariciones neotestamentarias incluye declaraciones memorables: «uno mayor que el templo está aquí» (Mt 12:6), «uno mayor que Jonás está aquí» (Mt 12:41) y el anuncio postpascual «no está aquí, pues ha resucitado» (Mt 28:6). En varios pasajes se desliza hacia «a este lugar» o «acá» (Mt 8:29; 14:18). La palabra es funcionalmente equivalente en todas las lenguas — español «aquí», francés ici, alemán hier —, confirmando su único sentido deíctico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5603', 'spa', 'Canción, oda o himno de alabanza; composición lírica destinada a ser cantada, especialmente en la adoración.', 'El sustantivo ᾠδή, contracción de ἀοιδή (''canción''), designa una composición lírica destinada a ser cantada. Cada aparición en el Nuevo Testamento se sitúa en un contexto de adoración o alabanza celestial. Pablo la empareja con salmos y cánticos espirituales como elementos del culto comunitario (Efesios 5:19; Colosenses 3:16), mientras que Apocalipsis presenta el ''cántico nuevo'' entonado ante el trono del Cordero (Apocalipsis 5:9; 14:3). Tanto el alemán ''Lied'' como el español ''cántico'' captan la cualidad lírica y festiva del término, distinguiéndola del mero discurso o recitación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5604', 'spa', 'Dolores de parto; figuradamente, las angustias intensas que preceden una nueva era o la liberación.', 'Enraizado en la agonía física del alumbramiento, este término se extiende poderosamente hacia la metáfora escatológica y teológica. Jesús lo emplea en el Discurso del Monte de los Olivos (Mt 24:8, Mc 13:8) para describir guerras y convulsiones como apenas el «principio de dolores de parto», implicando que el sufrimiento presente no carece de propósito, sino que es preludio de algo nuevo. Pablo lo retoma en 1 Tesalonicenses 5:3, donde la destrucción repentina sobreviene como dolor de parto a la mujer encinta. En Hechos 2:24, Pedro declara que Dios desató los «dolores de la muerte», evocando la imagen de una muerte en trabajo de parto incapaz de retener al Cristo resucitado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5605', 'spa', 'Estar de parto, sufrir dolores de alumbramiento; padecer angustia como de parto', 'Este verbo describe los dolores del parto o el estar de alumbramiento, y se extiende metafóricamente a cualquier angustia o lucha intensa. En Gálatas 4:19, Pablo escribe: «Hijitos míos, por quienes vuelvo a sufrir dolores de parto, hasta que Cristo sea formado en vosotros», expresando su agonía por la formación espiritual de los gálatas. Gálatas 4:27 cita Isaías 54:1, invitando a la estéril a regocijarse porque «más son los hijos de la desolada que los de la que tiene marido». Apocalipsis 12:2 presenta a la mujer vestida del sol «con dolores de parto, clamando por dar a luz». El término transmite tanto la angustia física como la espiritual al engendrar nueva vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5607', 'spa', 'siendo, estando; participio presente de ''ser/estar''', 'Esta forma participial de ''ser/estar'' funciona como adjetivo o adverbio, describiendo estados de existencia o circunstancias. A menudo proporciona información de trasfondo o explica las condiciones bajo las cuales ocurre una acción. Los escritores del Nuevo Testamento la emplean para caracterizar a personas según su condición o cualidades: siendo discípulos, siendo pobres, estando en cierto lugar. Como participio circunstancial, frecuentemente significa ''mientras es/está'' o ''puesto que es/está'', conectando el estado de ser con la acción principal de la oración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5610', 'spa', 'Hora, tiempo, momento; período que abarca desde una hora literal hasta un momento decisivo o señalado por Dios.', 'ὥρα abarca desde la hora literal —una doceava parte de la jornada diurna— hasta el momento teológicamente cargado o tiempo señalado. En contextos narrativos marca la hora del reloj (''la hora décima,'' Jn 1:39) o una duración. Con mayor profundidad, designa momentos dispuestos por Dios: Jesús habla repetidamente de ''mi hora'' como su tiempo destinado de glorificación a través del sufrimiento (Jn 2:4; 7:30; 12:23). La ''hora'' escatológica señala los tiempos finales (1 Jn 2:18). Las traducciones en todas las lenguas emplean cognados directos que captan tanto la dimensión temporal como la kairológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5611', 'spa', 'Hermoso, bello; originalmente ''oportuno'' o ''a su tiempo'', describiendo lo que es apropiado y atractivo en su momento justo.', 'Este adjetivo describía originalmente frutos madurados en su estación propicia, portando el sentido de oportunidad y belleza natural. En el Nuevo Testamento describe los sepulcros blanqueados de Mateo 23:27 — exteriormente hermosos pero interiormente corruptos — y la Puerta Hermosa del templo en Hechos 3:2, 10. Pablo cita a Isaías en Romanos 10:15 declarando «cuán hermosos son los pies de los que anuncian buenas nuevas». La palabra enlaza así el atractivo estético con una conveniencia más profunda, sugiriendo que la verdadera belleza está ligada al propósito y al momento oportuno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5613', 'spa', 'Como (comparativo); cuando (temporal); aproximadamente; cuan/como (exclamativo); como si; para (final); desde que.', 'La partícula griega ὡς es una de las palabras funcionales más versátiles del Nuevo Testamento, con más de 500 apariciones y un abanico semántico notablemente paralelo al de su homóloga hebrea כַּאֲשֶׁר. En su núcleo establece comparaciones —''sed perfectos como vuestro Padre celestial es perfecto'' (Mt 5:48)—, pero se desplaza con facilidad hacia los terrenos temporal, aproximativo, exclamativo e incluso final. Su flexibilidad se refleja en distintas lenguas: el francés comme cubre comparación y tiempo, el español como abarca comparación y exclamación, mientras que el alemán wie maneja comparación, tiempo y exclamación por igual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5614', 'spa', 'Hosanna; exclamación litúrgica hebrea que significa «¡Salva, te rogamos!», usada como aclamación de alabanza y esperanza mesiánica.', 'Hosanna transliterada del hebreo hoshi’ah-na («¡Salva ahora!» o «¡Salva, por favor!»), procede del Psalm 118:25, parte de los salmos del Hallel cantados en las grandes festividades. Para la época de Jesús, esta súplica urgente había evolucionado hacia un grito de aclamación gozosa y expectativa mesiánica. Las multitudes la proclaman en la Entrada Triunfal (Matt 21:9; Mark 11:9-10), emparejándola con «¡Bendito el que viene en el nombre del Señor!». Incluso los niños la repiten en el templo (Matt 21:15). Todas las traducciones conservan la palabra como transliteración —español «Hosana», francés «Hosanna», alemán «Hosanna»— reconociéndola como exclamación litúrgica que trasciende la traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5615', 'spa', 'Igualmente, del mismo modo, de manera similar; adverbio que señala acciones o comportamientos paralelos. Formado de ὡς (como) y αὐτός (mismo), este ad', 'Igualmente, del mismo modo, de manera similar; adverbio que señala acciones o comportamientos paralelos. Formado de ὡς (como) y αὐτός (mismo), este adverbio traza paralelos explícitos entre acciones. En las parábolas de Jesús estructura patrones repetidos: un terrateniente envía siervos a diferentes horas y cada uno responde ''igualmente'' (Mt 20:5); un padre pide a dos hijos y el segundo responde ''asimismo'' (Mt 21:30). También conecta instrucciones éticas — los diáconos ''igualmente'' deben ser dignos (1 Ti 3:8), las mujeres mayores ''asimismo'' reverentes (Tit 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5616', 'spa', 'aproximadamente, como (con números); como, como si, a manera de (en comparaciones)', 'aproximadamente, como (con números); como, como si, a manera de (en comparaciones)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5618', 'spa', 'Así como, tal como; adverbio comparativo que introduce analogías y semejanzas', 'Así como, tal como; adverbio comparativo que introduce analogías y semejanzas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5620', 'spa', 'De modo que, por lo tanto — conjunción consecutiva que introduce resultado, consecuencia o conclusión lógica', 'El griego ὥστε (de ὡς + τε) es una conjunción consecutiva que introduce el resultado o la conclusión lógica de lo anteriormente expuesto. Aparece 83 veces en el Nuevo Testamento y funciona en dos construcciones principales: con infinitivo para expresar un resultado natural o esperado (''de modo que,'' Mt 8:24), y con verbo en forma finita o como conector oracional con el sentido de ''por lo tanto'' o ''así que'' (Mt 12:12; 1 Co 3:21). Pablo la emplea con frecuencia para extraer conclusiones prácticas de argumentos teológicos (1 Co 3:7; 4:5; Fil 2:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5621', 'spa', 'oreja — la oreja externa o pabellón auricular, el órgano físico de la audición', 'ὠτίον es un diminutivo de οὖς (''oído, oreja''), que originalmente significaba ''orejita'' o ''aurícula'', aunque en el uso neotestamentario la fuerza diminutiva se ha perdido y simplemente significa ''oreja''. Las cinco apariciones se agrupan en torno a un solo episodio dramático: el corte y la sanación de la oreja en Getsemaní. Cada evangelio narra el momento en que Pedro golpea al siervo del sumo sacerdote y le corta la oreja (Mt 26:51; Mr 14:47; Jn 18:10, 26), y solo Lucas registra que Jesús la tocó y la sanó (Lc 22:51). El sentido es uniformemente anatómico y concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5623', 'spa', 'Aprovechar, beneficiar o ser de utilidad; usado transitivamente para ayudar a otros e intransitivamente para ser útil. Un verbo con sabor práctico y d', 'Aprovechar, beneficiar o ser de utilidad; usado transitivamente para ayudar a otros e intransitivamente para ser útil. Un verbo con sabor práctico y de mercado que plantea la eterna pregunta: ¿de qué sirve? Jesús pregunta: «¿Qué aprovecha al hombre ganar el mundo entero y perder su alma?» (Mc 8:36; Mt 16:26). Pablo insiste en que la circuncisión aprovecha si se guarda la ley (Ro 2:25) y que las lenguas sin interpretación no aprovechan nada (1 Co 14:6). La palabra puede adoptar tres formas: pasiva (''ser beneficiado''), absoluta (''ser de provecho'') o transitiva (''beneficiar a alguien''). Hebreos 4:2 señala conmovedoramente que la palabra predicada ''no les aprovechó'' a los oyentes que carecían de fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G5624', 'spa', 'Beneficioso, provechoso, útil; lo que produce una ventaja genuina o un bien práctico.', 'Un adjetivo directo de valor práctico que evalúa las cosas según el beneficio real que producen. Pablo lo emplea en 1 Timoteo 4:8 para trazar una comparación memorable: el ejercicio corporal es provechoso para poco, pero la piedad lo es para todo. En 2 Timoteo 3:16 toda Escritura se declara «útil» para enseñar y corregir. Tito 3:8 exhorta a los creyentes hacia las buenas obras que son «provechosas» para las personas. En todas sus apariciones, el término subraya una utilidad tangible y práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0001', 'spa', 'Padre: progenitor masculino directo; antepasado o patriarca (plural); jefe de casa paterna en la organizacion tribal de Israel.', 'La palabra hebrea אָב es uno de los terminos de parentesco mas fundamentales de la Escritura, con mas de 1.200 apariciones y un peso que va mucho mas alla de la biologia. Designa al padre inmediato en las narrativas familiares (Gn 2:24, ''dejara el hombre a su padre''), pero su forma plural אָבוֹת se extiende a generaciones anteriores con el significado de ''antepasados'' o ''patriarcas'' — aquellos con quienes Dios hizo pacto. Lenguas como el coreano distinguen netamente entre 아버지 (padre) y 조상 (antepasado), y el hindi entre पिता y पूर्वज, revelando que lo que el hebreo condensa en una sola raiz, muchas lenguas separan. Un sentido institucional especializado aparece en Cronicas, donde ''casas paternas'' (בֵּית אָבוֹת) designan las divisiones claniles que organizaban el ejercito, el sacerdocio y el censo de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0002', 'spa', 'Padre, ancestro; sustantivo arameo usado en Daniel y Esdras para figuras paternas y antepasados.', 'Sustantivo arameo que significa ''padre'' o ''ancestro'', presente exclusivamente en las porciones arameas de Daniel y Esdras. Funciona de manera idéntica a su cognado hebreo אָב pero con morfología aramea, recibiendo diversos sufijos pronominales: ''mi padre'', ''tus padres'', ''nuestros padres''. En Daniel 5:2 y 5:11 se refiere a Nabucodonosor como ''padre'' de Belsasar (probablemente abuelo o predecesor), mientras que en Esdras 4:15 habla de los ''padres'' de los opositores de Israel. Las traducciones multilingües lo traducen uniformemente como ''padre'', confirmando su sentido directo de parentesco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0004', 'spa', 'fruto (arameo); el producto de un árbol o planta', 'Este sustantivo arameo significa fruto, el producto de árboles o plantas. Las tres apariciones se encuentran en Daniel 4, dentro del sueño de Nabucodonosor sobre el gran árbol. El árbol tenía «fruto abundante» (v. 12), que alimentaba a todos. Cuando el vigía celestial decreta la tala del árbol, ordena: «Sacudid sus hojas y esparcid su fruto» (v. 14). La descripción se repite: «cuyo fruto era abundante» (v. 21). Daniel interpreta el árbol como representación del propio Nabucodonosor: la prosperidad y provisión de su reino se retratan como fruto abundante, evocando la ideología real del antiguo Cercano Oriente, donde el rey es un gran árbol que ofrece sombra y sustento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0006', 'spa', 'Perecer, ser destruido; en Piel, destruir o aniquilar; en Hifil, hacer perecer; también perderse, extraviarse.', 'אָבַד es el verbo primordial de la pérdida terminal en la Biblia hebrea, ya sea por juicio divino, desastre bélico, deterioro natural o simple extravío. Su forma Qal porta el peso intransitivo: las naciones perecen, los impíos son destruidos, la memoria se desvanece. El Piel intensifica esto hacia la aniquilación activa y deliberada: a Israel se le ordena ''destruir por completo'' los santuarios cananeos (Dt 12:2). El Hifil añade un estrato causativo: Dios mismo hace perecer al desobediente (Dt 7:10). Sin embargo, la misma raíz también significa simplemente ''perderse'': una burra extraviada (1 S 9:3), un arameo errante (Dt 26:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0007', 'spa', 'Perecer o destruir — verbo arameo que significa perderse o arruinarse (intransitivo) o causar destrucción (Hifil causativo).', 'Este cognado arameo del hebreo אָבַד (H0006) aparece exclusivamente en Daniel y una vez en el versículo arameo de Jeremías. En su forma Hifil (causativa), transmite el sentido contundente de aniquilación real o divina: Nabucodonosor decreta destruir a los sabios de Babilonia (Dn 2:12, 18, 24), y el Anciano de Días quita el dominio para destruirlo completamente (Dn 7:26). En sus formas intransitivas, la palabra describe el destino de quienes enfrentan tal poder: los dioses que no hicieron cielo ni tierra «perecerán» (Jer 10:11), y la bestia espantosa «fue destruida» (Dn 7:11). El contexto cortesano arameo le confiere un matiz de decreto imperial y juicio apocalíptico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0009', 'spa', 'Cosa perdida; objeto extraviado que aguarda ser recuperado por su legítimo dueño.', 'Este sustantivo se refiere específicamente a un bien que se ha perdido y que puede ser hallado por otra persona. Aparece en los códigos legales de Éxodo y Levítico que regulan la obligación de devolver objetos encontrados, y en la detallada legislación de Deuteronomio sobre bienes extraviados. La palabra se construye sobre la raíz álef-bet-dálet (perecer, perderse) con un patrón nominal femenino que indica el objeto mismo. La ley israelita antigua tomaba muy en serio la recuperación y devolución de lo perdido: encontrar algo no lo hacía propio, y ocultar un objeto hallado constituía una forma de hurto que requería restitución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000b', 'spa', 'en, con, por, a través de; preposición que indica lugar, medio o asociación', 'Esta diminuta preposición tiene un peso enorme en hebreo, pues expresa relaciones que en español captamos con múltiples palabras: en, por, con, a través de, entre, durante. Ubica cosas en el espacio y el tiempo, indica el medio o instrumento por el cual algo sucede y señala circunstancias acompañantes. El hebreo la combina con incontables modismos: ''en la mano de'' significa ''por medio de'', ''a los ojos de'' significa ''según la opinión de'', ''en aquel día'' marca un momento específico. Dominar sus matices es esencial para leer el hebreo con precisión, ya que establece las relaciones fundamentales entre las palabras de una oración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000c', 'spa', 'y, entonces, así que; conjunción que conecta cláusulas, oraciones o secuencias narrativas', 'La palabra más frecuente del hebreo, esta sencilla conjunción hace mucho más que unir palabras. Secuencia la narrativa (''y entonces''), añade información (''y también''), contrasta ideas (''pero''), introduce explicaciones (''pues'') y marca acciones consecutivas (''así que''). La narración hebrea antigua depende en gran medida del patrón waw-consecutivo, donde cada acción sigue a la anterior con ''y''. Su fuerza demostrativa a veces la vuelve enfática —''y así fue que''—, dándole a la narrativa hebrea su ritmo distintivo. El contexto determina si significa ''y'', ''pero'', ''entonces'', ''así que'' o ''pues'', lo que la hace tan ubicua como flexible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000d', 'spa', 'el, la, los, las; artículo definido que marca referentes conocidos, específicos o únicos', 'Este prefijo transforma cualquier sustantivo de indefinido a definido, señalando ''el específico'' en lugar de ''uno entre muchos''. Marca elementos previamente mencionados, identificados de forma única o contextualmente evidentes. El hebreo lo emplea con mayor libertad que el español: ante sustantivos genéricos o representativos (''el león'' refiriéndose a los leones en general), con cualidades abstractas y a veces simplemente para dar énfasis. A diferencia del griego, el hebreo nunca lo omite por efecto estilístico; su presencia o ausencia sigue patrones consistentes. Combinado con participios, crea sustantivos (''el que juzga'' se convierte en ''el juez''), algo fundamental para comprender la gramática hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000i', 'spa', 'partícula interrogativa que introduce preguntas; prefijo ''si'' o independiente ''¿acaso?''', 'Esta partícula convierte cualquier afirmación en pregunta. Puede introducir preguntas genuinas cuya respuesta se desconoce, o preguntas retóricas que esperan una respuesta determinada, generalmente negativa. El hebreo bíblico la utiliza con frecuencia para expresar sorpresa, indignación o ironía. A veces aparece en preguntas indirectas (''si acaso'') o en preguntas deliberativas donde el hablante se pregunta qué hacer. Su tono varía drásticamente según el contexto: desde el directo ''¿Iré?'' de Moisés hasta las incisivas preguntas retóricas de Dios en Job, donde la respuesta esperada subraya la limitación humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000k', 'spa', 'como, según, conforme a; preposición que expresa semejanza, comparación o correspondencia', 'Esta preposición establece semejanza o conformidad entre dos cosas. Aparece en comparaciones (''fuerte como un león''), en expresiones de manera (''haced conforme a la ley'') y en medidas aproximadas (''como unos cien''). La literatura profética la emplea para símiles: ''como ovejas sin pastor'', ''como un padre se compadece de sus hijos''. Los textos legales la usan para indicar conformidad con una norma. La partícula puede significar ''aproximadamente'', ''a la manera de'', ''en proporción a'' o simplemente ''como'', lo que hace indispensable atender al contexto para una traducción precisa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000l', 'spa', 'a, para, hacia; preposición que indica dirección, propósito, posesión o referencia', 'Quizá la preposición más versátil del hebreo, esta partícula expresa dirección (movimiento hacia), propósito (para beneficio de), posesión (perteneciente a), referencia (respecto a), ventaja (en favor de) e incluso dativo ético (desde la perspectiva de alguien). El contexto determina si ''a David'' significa ''hacia David'', ''para beneficio de David'', ''en opinión de David'' o ''perteneciente a David''. El hebreo la combina con infinitivos para expresar propósito (''a fin de'') y con pronombres para indicar objetos indirectos. Comprender su alcance es esencial para una interpretación matizada del texto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000m', 'spa', 'de, desde, fuera de; preposición que indica origen, separación o relación partitiva', 'Esta preposición marca separación, origen o punto de partida, tanto espacial como conceptual. Indica movimiento físico desde un lugar, el material del que algo está hecho, la fuente de una acción, la causa de una condición o una porción tomada de un todo. Las advertencias proféticas hablan de apartarse «de» los caminos malvados; los Salmos alaban la liberación «de» los enemigos. Se combina con otras preposiciones para crear significados complejos e introduce comparaciones («más que»). Su flexibilidad la hace esencial para expresar relaciones de origen, separación, causalidad y partición a lo largo de las Escrituras hebreas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H000s', 'spa', 'que, el cual, quien; partícula relativa que conecta cláusulas e introduce enunciados relativos', 'Esta partícula relativa abreviada (forma reducida de la variante más larga) introduce cláusulas relativas y aparece frecuentemente en los libros bíblicos tardíos, especialmente Eclesiastés y Cantar de los Cantares. Cumple la misma función que el relativo más extenso y común: introducir cláusulas que describen o identifican un sustantivo. Donde el hebreo más antiguo diría «el hombre que vino», los textos posteriores prefieren esta forma abreviada. La partícula evidencia la evolución lingüística dentro de las Escrituras, ya que el hebreo hablado fue favoreciendo progresivamente las formas más breves. Su presencia ayuda a los estudiosos a identificar fechas de composición más tardías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0010', 'spa', 'Abadón, lugar de destrucción; el reino de los muertos como lugar de ruina y perdición', 'La literatura sapiencial personifica este ámbito como el lugar donde los muertos experimentan destrucción y ruina. En paralelo con el Seol y la muerte misma, Abadón representa no meramente la tumba, sino la condición de estar completamente arruinado y separado de la vida. Job pregunta retóricamente si las maravillas de Dios son conocidas en Abadón, sugiriendo la profunda separación de la presencia divina. El término enfatiza el aspecto destructivo de la muerte más que su simple finalidad. La tradición judía y cristiana posterior personificó a Abadón como un ángel destructor, pero el uso bíblico lo mantiene como un lugar o estado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0011', 'spa', 'Abadón; el lugar de destrucción o ruina en el Seol, el reino de los muertos personificado como potencia cósmica.', 'Abadón (de la raíz אָבַד, ''perecer'') designa el lugar de destrucción total dentro del mundo subterráneo. En la literatura sapiencial aparece como sinónimo poético de Seol y la tumba, emparejado con la muerte misma (Job 28:22) y con el abismo (Job 26:6; Pr 15:11). La palabra sugiere no simplemente muerte, sino aniquilación — un lugar sin retorno. En Apocalipsis 9:11, la forma griega Ἀβαδδών se convierte en nombre propio del ángel del abismo, mostrando cómo este concepto hebreo se trasladó a la imaginería apocalíptica. El español «perdición» conserva la fuerza destructiva de la raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0014', 'spa', 'Estar dispuesto, consentir; expresa disposición volitiva o acuerdo deliberado, muy frecuentemente negado.', 'Verbo de voluntad que expresa la disposición interior de alguien — o, con mucha mayor frecuencia, su obstinada negativa — a actuar. La gran mayoría de sus apariciones van acompañadas de una partícula negativa: ''no quiso.'' Faraón ''no quiso'' dejar ir a Israel (Éx 10:27); Israel ''no quiso'' subir a la tierra (Dt 1:26); Nabal ''no quiso'' escuchar (1 S 25:10). Cuando Dios es el sujeto, las implicaciones son inmensas: ''Jehová no quiso destruir'' (2 R 13:23). Los cognados en árabe y etiópico significan propiamente ''rehusar,'' lo que sugiere que el sentido negativo podría estar más cerca del núcleo antiguo de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0018', 'spa', 'pesebre, comedero; lugar donde comen los animales domésticos', 'Este sustantivo hebreo designa un pesebre o comedero donde los animales domésticos se alimentan. En Job 39:9, Dios pregunta a Job si el búfalo salvaje accederá a pasar la noche «junto a tu pesebre», subrayando su naturaleza indomable a diferencia del ganado doméstico. Proverbios 14:4 observa: «Donde no hay bueyes, el pesebre está limpio; pero mucha ganancia viene por la fuerza del buey», un dicho sapiencial sobre el equilibrio entre comodidad y productividad. Isaías 1:3 lamenta la insensibilidad espiritual de Israel: «El buey conoce a su dueño, y el asno el pesebre de su amo; pero Israel no entiende, mi pueblo no tiene discernimiento». Incluso los animales reconocen la fuente de su sustento; el pueblo de Dios, no.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0022', 'spa', 'Abiel; nombre propio que significa «El (Dios) es mi padre»', 'Este nombre propio hebreo significa «El es (mi) padre» o «Dios es padre», un nombre teofórico que afirma la relación con lo divino. Abiel fue el abuelo de Saúl (1 Samuel 9:1; 14:51), lo que lo sitúa en la primera línea real de Israel. El nombre también aparece en 1 Crónicas 11:32, posiblemente refiriéndose al mismo individuo o a otro guerrero. Estos nombres eran comunes en el antiguo Israel y expresaban la fe y esperanza de los padres. El elemento «El» remite al Dios altísimo de Israel, mientras que «abi» (mi padre) refleja una relación íntima, un patrón que se repite en nombres bíblicos como Abías, Abimelec y otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0024', 'spa', 'Espigas tiernas de grano (cebada); también el mes de Aviv (= Nisán), primer mes del calendario hebreo cuando maduran las espigas.', 'Aviv conecta el calendario agrícola con la historia de salvación de Israel. La palabra se refiere fundamentalmente a las espigas tiernas de cebada que comienzan a formarse, en la etapa previa a la madurez plena (Ex 9:31, Lv 2:14). Esta realidad agrícola dio nombre al primer mes del año hebreo, el mes del Éxodo y la Pascua (Ex 13:4, 23:15, 34:18, Dt 16:1), llamado después Nisán en el período postexílico. El español emplea ''espiga'' para el sentido concreto y ''Aviv'' para el nombre del mes, reflejando bien este doble uso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0025', 'spa', 'Gabaón, ciudad levítica en Benjamín; sitio de la victoria de Josué y la visión de Salomón', 'Esta ciudad hevea alcanzó fama cuando sus habitantes engañaron astutamente a Josué para que hiciera un pacto con ellos, convirtiéndose en siervos de Israel en lugar de sufrir la destrucción. El gran estanque de Gabaón fue testigo de la contienda entre los hombres de Joab y las fuerzas de Abner. Salomón recibió aquí su sueño de sabiduría en el lugar alto, antes de que se construyera el templo. Los profetas posteriores condenaron el culto ilegítimo en Gabaón, aunque su importancia histórica seguía siendo innegable. La identificación arqueológica con la moderna Tell el-Jib ha revelado extensos sistemas hidráulicos que coinciden con las descripciones bíblicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0026', 'spa', 'Abigail: nombre propio que significa ''mi padre es gozo'', llevado por dos mujeres vinculadas a la casa de David. Abigail (אֲבִיגַיִל) probablemente sig', 'Abigail: nombre propio que significa ''mi padre es gozo'', llevado por dos mujeres vinculadas a la casa de David. Abigail (אֲבִיגַיִל) probablemente significa ''mi padre es gozo'' o ''fuente de gozo''. El nombre pertenece de manera más prominente a la esposa sabia e ingeniosa de Nabal el carmelita, quien interceptó la ira de David con provisiones y un discurso elocuente (1 Sam 25). Tras la muerte de Nabal, ella se convirtió en esposa de David y lo acompañó durante sus años en el desierto. Una segunda Abigail aparece como hermana o media hermana de David (1 Cr 2:16-17), madre de Amasa. El nombre aparece en varias variantes ortográficas en los manuscritos hebreos, reflejando el tratamiento escribal de la terminación yod-lamed.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0027', 'spa', 'Abidán — príncipe benjaminita cuyo nombre significa ''mi padre es juez''', 'אֲבִידָן aparece cinco veces en Números como el líder designado de la tribu de Benjamín durante el período del desierto. Su nombre, que significa ''mi padre es juez'', sigue el patrón teofórico común de los nombres israelitas construidos sobre אָב (''padre''). Figura en el censo (Nm 1:11), la disposición del campamento (Nm 2:22) y las ofrendas de dedicación del tabernáculo (Nm 7:60, 65; 10:24). La evidencia multilingüe es uniforme — ''Abidán'' en español, francés y alemán — lo que refleja la transliteración directa de un único referente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0029', 'spa', 'Abías; nombre teofórico que significa ''Yah(u) es mi padre'', llevado por reyes, sacerdotes y otras figuras bíblicas', 'Abías; nombre teofórico que significa ''Yah(u) es mi padre'', llevado por reyes, sacerdotes y otras figuras bíblicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0030', 'spa', 'Abiú — hijo de Aarón, consumido por fuego divino por ofrecer incienso no autorizado ante el SEÑOR. Abiú (hebreo אֲבִיהוּא, ''él es mi padre'') fue el se', 'Abiú — hijo de Aarón, consumido por fuego divino por ofrecer incienso no autorizado ante el SEÑOR. Abiú (hebreo אֲבִיהוּא, ''él es mi padre'') fue el segundo hijo de Aarón el sumo sacerdote y Elisabet (Éx 6:23). Estuvo entre quienes ascendieron al Sinaí y contemplaron al Dios de Israel (Éx 24:1, 9), y fue consagrado para el servicio sacerdotal junto con su padre y hermanos (Éx 28:1). Su muerte, junto con la de su hermano Nadab, por ofrecer ''fuego extraño'' (esh zarah) ante el SEÑOR (Lv 10:1-2) se convirtió en una de las advertencias más solemnes del Antiguo Testamento sobre la santidad exigida en la adoración. El incidente se recuerda repetidamente en Números y 1 Crónicas como paradigma de la responsabilidad sacerdotal. Las doce apariciones se refieren al mismo individuo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0032', 'spa', 'Abihail; nombre propio que significa «mi padre es fortaleza», llevado por varios hombres y mujeres en la Biblia hebrea.', 'Abihail (אֲבִיחַיִל) combina «avi» («mi padre») con «chayil» («fuerza, poder»), dando el significado teofórico «mi padre es fortaleza» o «padre de poder». Este nombre lo llevan al menos cinco personas distintas: un jefe de clan levita (Num 3:35), un gadita (1 Chr 5:14), el padre de la reina Ester (Esth 2:15; 9:29), la esposa de Abisur (1 Chr 2:29) y una esposa de Roboám (2 Chr 11:18). El español y el francés conservan variantes reconocibles —Abihail, Abijail, Abichail— que apuntan todas al mismo nombre compuesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0033', 'spa', 'abiezerita; gentilicio que significa «perteneciente al clan de Abiezer»', 'Este adjetivo gentilicio hebreo identifica a alguien como miembro del clan de Abiezer, una familia dentro de la tribu de Manasés. Las tres apariciones se relacionan con Gedeón, el juez que libró a Israel de la opresión madianita. Jueces 6:11 presenta a «Joás abiezerita», padre de Gedeón. Jueces 6:24 señala que Gedeón edificó un altar en Ofra, «que pertenecía a Joás abiezerita». Jueces 8:32 registra la sepultura de Gedeón «en el sepulcro de Joás su padre, en Ofra de los abiezeritas». El nombre del clan se remonta a Abiezer, mencionado en Números 26:30 como hijo (clan) de Galaad en el linaje de Manasés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0034', 'spa', 'Necesitado, pobre, indigente; persona materialmente empobrecida y vulnerable', 'El adjetivo אֶבְיוֹן describe a una persona en extrema necesidad material — el genuinamente indigente y vulnerable, no simplemente el modesto o humilde. Es el término más fuerte del vocabulario hebreo de la pobreza, frecuentemente emparejado con עָנִי (''afligido/pobre'') y דַּל (''débil/humilde'') para formar una tríada profética que denuncia la opresión social. Amós truena contra quienes ''venden al necesitado por un par de sandalias'' (Am 2:6; 8:6), y la legislación deuteronómica insiste repetidamente en la generosidad: ''no endurecerás tu corazón ni cerrarás tu mano contra tu hermano pobre'' (Dt 15:7). Los Salmos celebran a Dios como defensor del אֶבְיוֹן (Sal 37:14; 109:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0038', 'spa', 'Abiyam — rey de Judá, hijo y sucesor de Roboam, también escrito Abías', 'אֲבִיָּם es la forma utilizada en 1 Reyes para el rey de Judá que sucedió a Roboam y reinó brevemente (ca. 913-911 a.C.). El mismo rey es llamado אֲבִיָּהוּ en Crónicas y אֲבִיָּה en otros pasajes, lo que refleja variantes ortográficas de un nombre que significa ''Yah(u) es mi padre''. Sus cinco apariciones en 1 Reyes (14:31; 15:1, 7, 7, 8) enmarcan un reinado descrito como continuación de los pecados de su padre. La Septuaginta lo traduce como Abiou o Abia, y las glosas multilingües transliteran de forma consistente a este mismo monarca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0040', 'spa', 'Abimelec — ''mi padre es rey''; nombre propio de reyes filisteos, del hijo de Gedeón y de un sacerdote', 'Abimelec (אֲבִימֶלֶךְ, ''mi padre es rey'') es un nombre propio teofórico compartido por varias figuras del Antiguo Testamento. Los más destacados son el rey filisteo de Gerar que interactúa tanto con Abraham (Gn 20-21) como con Isaac (Gn 26), y el ambicioso hijo de Gedeón que masacró a sus setenta hermanos para apoderarse del poder en Siquem (Jue 9). Un tercer portador aparece en el encabezado del Salmo 34:1, probablemente un nombre dinástico sustituido por Aquis el filisteo. La estructura del nombre — ''mi padre es rey'' — puede reflejar un título dinástico más que un nombre personal en las narrativas de Gerar, de modo similar a como funcionaba ''Faraón'' en Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0041', 'spa', 'Abinadab — nombre propio masculino que llevan varios personajes del AT, incluido el hombre que albergó el arca en Quiriat-jearim. Abinadab (hebreo אֲב', 'Abinadab — nombre propio masculino que llevan varios personajes del AT, incluido el hombre que albergó el arca en Quiriat-jearim. Abinadab (hebreo אֲבִינָדָב, ''mi padre es noble/generoso'') es un nombre propio llevado por al menos tres individuos distintos en la Biblia hebrea: (1) un hombre de Quiriat-jearim en cuya casa se guardó el arca del pacto durante veinte años tras su retorno de Filistea (1 S 7:1; 2 S 6:3-4); (2) el segundo hijo de Isaí y hermano mayor de David, presente cuando Samuel vino a ungir un nuevo rey (1 S 16:8; 17:13); y (3) un hijo del rey Saúl que cayó con él en la batalla del monte Gilboa (1 S 31:2; 1 Cr 8:33; 9:39; 10:2). Las doce apariciones llevan la misma forma léxica con solo variación sintáctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0042', 'spa', 'Abinoam, nombre propio que significa ''mi padre es deleite''; padre del juez Barac.', 'Un nombre propio hebreo compuesto de אָב (padre) y נֹעַם (deleite, amabilidad), con el significado teofórico «mi padre es deleite» o «el Padre [divino] es bondadoso». Abinoam es conocido únicamente como padre de Barac, el comandante militar que la profetisa Débora convocó para dirigir a Israel contra las fuerzas cananeas de Sísara. El nombre aparece cuatro veces en Jueces 4-5, siempre en la fórmula patronímica «Barac hijo de Abinoam», anclando la identidad de Barac en su linaje familiar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0043', 'spa', 'Ebiasaf (Abiasaf); nombre propio que significa «mi padre ha reunido» o «el padre ha añadido»', 'Este nombre propio hebreo significa «mi padre ha reunido» o «el padre ha añadido», un nombre teofórico que expresa gratitud o esperanza. Ebiasaf (o Abiasaf, variante ortográfica) fue descendiente de Coré, en la línea levítica. El nombre aparece en 1 Crónicas 6:23, 37 y 9:19, dentro de genealogías levíticas. Éxodo 6:24 lo menciona como hijo de Coré. A pesar de la rebelión de Coré (Números 16), sus descendientes sobrevivieron y llegaron a ser porteros y músicos en el culto de Israel. La preservación del linaje de Coré testifica de la misericordia de Dios: los hijos no fueron destruidos junto con su ancestro rebelde, sino que sirvieron en el santuario por generaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0044', 'spa', 'Abiezer (lit. ''mi padre es ayuda''); nombre propio de un ancestro del clan manasita y de un guerrero benjaminita.', 'El nombre Abiezer significa ''mi padre es ayuda'', combinando אָב (''padre'') y עֵזֶר (''ayuda''). Identifica a dos figuras distintas en el Antiguo Testamento: primero, el ancestro del clan manasita cuyos descendientes incluyen a Gedeón (Jue 6:34; 8:2; Jos 17:2), y segundo, un guerrero benjaminita entre los valientes de David (2 S 23:27; 1 Cr 11:28; 27:12). El clan de Abiezer desempeña un papel destacado en la narrativa de Gedeón, donde «el Espíritu de Jehová revistió a Gedeón, y tocó la trompeta, y los abiezeritas fueron convocados para seguirlo».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0046', 'spa', 'Poderoso; epíteto divino poético para Dios, siempre en estado constructo (''Poderoso de Jacob/Israel''), expresando poder soberano.', 'Avir es un epíteto majestuoso y arcaico para Dios que aparece exclusivamente en textos poéticos y proféticos. Siempre se presenta en estado constructo —''Poderoso de Jacob'' o ''Poderoso de Israel''— y nunca como sustantivo independiente para referirse a Dios. La bendición de Jacob en Génesis 49:24 lo introduce por primera vez: los brazos de las manos de José fueron fortalecidos ''por las manos del Poderoso de Jacob''. Isaías lo emplea tanto en juicio (1:24, ''el Poderoso de Israel'') como en promesa (49:26; 60:16). Las traducciones multilingües revelan su peso semántico: español Fuerte/Poderoso, francés Puissant, alemán Starker —todos términos autoritativos reservados para el poder divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0047', 'spa', 'Poderoso, fuerte; usado para guerreros, animales robustos (toros, sementales), los obstinados de corazón o un jefe/líder. Arraigado en la idea de fuer', 'Poderoso, fuerte; usado para guerreros, animales robustos (toros, sementales), los obstinados de corazón o un jefe/líder. Arraigado en la idea de fuerza bruta y poder, este adjetivo aparece casi exclusivamente en la poesía y siempre funciona como sustantivo: ''un poderoso''. Puede describir guerreros humanos a quienes Dios aplasta (Job 34:20), toros poderosos como los de Basán (Sal 22:13), o sementales veloces que tronan en la batalla (Jer 8:16). En Isaías 46:12 adquiere un matiz moral, designando a los ''fuertes de corazón'' que tercamente resisten los propósitos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0048', 'spa', 'Abiram — nombre propio hebreo que significa ''mi padre es exaltado'', llevado por el rebelde rubenita y por un hijo de Hiel. El nombre propio אֲבִירָם (', 'Abiram — nombre propio hebreo que significa ''mi padre es exaltado'', llevado por el rebelde rubenita y por un hijo de Hiel. El nombre propio אֲבִירָם (Abiram), que significa ''mi padre es exaltado'' (o ''el Exaltado es mi padre''), identifica a dos personajes distintos en el Antiguo Testamento. El referente principal es el rubenita hijo de Eliab que, junto con Datán y bajo el liderazgo de Coré, desafió la autoridad de Moisés y Aarón. La tierra se abrió y los tragó vivos como juicio divino (Nm 16:1-33), acontecimiento recordado como advertencia en Deuteronomio 11:6 y Salmo 106:17. El segundo Abiram es el hijo menor de Hiel el betelita, quien murió cuando su padre reconstruyó Jericó, cumpliendo la maldición de Josué (1 R 16:34).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0049', 'spa', 'Abisag -- la joven sunamita que atendió al rey David en su vejez', 'Abisag aparece en el relato de los últimos días de David y la sucesión salomónica temprana (1 Re 1-2). Era una joven sunamita de gran belleza, llevada para dar calor al rey anciano. Se convirtió en figura clave cuando la petición de Adonías de casarse con ella fue interpretada por Salomón como una pretensión velada al trono (1 Re 2:17-22). Su nombre, que posiblemente significa «mi padre vaga», aparece cinco veces. Las traducciones multilingües muestran una transliteración consistente, variando solo en el prefijo conjuntivo («y-Abisag») según las distintas tradiciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0050', 'spa', 'Abisúa -- nombre de un descendiente de Aarón y de un benjaminita, que significa «mi padre es salvación»', 'Abisúa es un nombre propio que aparece cinco veces en la Biblia hebrea y significa «mi padre es salvación» o posiblemente «mi padre es abundancia». Designa a dos individuos: un nieto de Finees en la línea sacerdotal aarónica (1 Cr 6:4-5, 50; Esd 7:5) y un benjaminita hijo de Bela (1 Cr 8:4). La genealogía sacerdotal constituye el contexto principal, ya que traza la sucesión del sumo sacerdocio desde Aarón a través de Eleazar, Finees y Abisúa. Las versiones francesa y alemana conservan la forma hebrea sin traducir, mientras que el inglés y el español la transliteran directamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0052', 'spa', 'Abisai; sobrino de David y guerrero valiente, hijo de Sarvia y hermano de Joab, cuyo nombre significa ''mi padre es un don''', 'Abisai; sobrino de David y guerrero valiente, hijo de Sarvia y hermano de Joab, cuyo nombre significa ''mi padre es un don''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0053', 'spa', 'Absalón — nombre propio que significa ''mi padre es paz''; tercer hijo de David que encabezó una célebre rebelión.', 'אֲבִישָׁלוֹם o אַבְשָׁלוֹם (Absalón) es un nombre propio hebreo compuesto de אָבִי (''mi padre'') y שָׁלוֹם (''paz''). Designa principalmente al tercer hijo del rey David, cuya historia de rebelión y trágica muerte domina 2 Samuel 13-18 y constituye una de las narrativas más conmovedoras de la Escritura. Un personaje secundario con este nombre aparece como padre de Maacá en 1 Reyes 15:2, 10. El español y el francés conservan las formas familiares ''Absalón'' y ''Absalom,'' mientras que la grafía hebrea alterna entre las dos formas según las tradiciones textuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0054', 'spa', 'Abiatar; sacerdote, hijo de Ahimelec, que sirvió fielmente a David pero fue desterrado por Salomón', 'Abiatar; sacerdote, hijo de Ahimelec, que sirvió fielmente a David pero fue desterrado por Salomón');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0056', 'spa', 'Hacer duelo, lamentar, llorar; de personas en luto por los muertos y figuradamente de la tierra que languidece', 'Hacer duelo, lamentar, llorar; de personas en luto por los muertos y figuradamente de la tierra que languidece');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0057', 'spa', 'Enlutado, afligido; adjetivo que describe a quien lamenta, ya sea por los muertos, por calamidad o por Sion.', 'Adjetivo hebreo que significa ''enlutado'' o ''en estado de duelo'', usado tanto como predicado como sustantivado (''un doliente''). Jacob declara que descenderá al Seol de luto por José (Gn 37:35), Mardoqueo regresa a casa enlutado tras la promoción de Amán (Est 6:12), y el salmista anda ''como quien llora por un amigo'' (Sal 35:14). Isaías lo extiende a quienes lloran por Sion (Is 61:2-3), otorgando al término una dimensión profético-escatológica. El español ''los que lloran'' y ''enlutado'' captan bien el carácter público y social de este duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0058', 'spa', 'Abel, pradera; componente en topónimos, posiblemente indicando tierras bajas fértiles', 'Este término geográfico aparece en topónimos compuestos a lo largo del antiguo Israel y sus vecinos, denotando aparentemente praderas o llanuras fértiles. Abel-bet-maacá, en el extremo norte, dio refugio a Seba durante su rebelión y luego entregó su cabeza para salvar la ciudad. Abel-sitim, en las llanuras moabitas, fue testigo del pecado de Israel con las mujeres moabitas. Los diversos Abel —de las acacias, de las viñas, de la danza— sugieren regiones agrícolas productivas. La conexión del término con el duelo es homofónica pero distinta, aunque algunos topónimos pueden implicar un juego de palabras entre ambos significados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0059', 'spa', 'Abel, topónimo que significa ''pradera'' o ''arroyo''; designa una ciudad fortificada en el norte de Israel, Abel Bet Maacá.', 'No debe confundirse con el nombre personal Abel (הֶבֶל) de Génesis 4. Este es un término geográfico que significa «pradera» o «vega», usado como topónimo para varias localidades del antiguo Israel. La más prominente es Abel Bet Maacá, una ciudad fortificada en el extremo norte donde Joab sitió al rebelde Seba hijo de Bicrí (2 S 20). Una mujer sabia dentro de la ciudad negoció su salvación entregando la cabeza de Seba. El sitio se identifica con el moderno Tell Abil el-Qamh, al noroeste de Dan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0060', 'spa', 'duelo, lamentación — período de luto formal por los muertos o expresión comunitaria de dolor ante una calamidad', 'duelo, lamentación — período de luto formal por los muertos o expresión comunitaria de dolor ante una calamidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0061', 'spa', 'Adverbio hebreo cuya fuerza semántica cambió con el tiempo. En la literatura narrativa más antigua (Génesis a Reyes) tiene valor aseverativo: ''ciertam', 'Adverbio hebreo cuya fuerza semántica cambió con el tiempo. En la literatura narrativa más antigua (Génesis a Reyes) tiene valor aseverativo: ''ciertamente'', ''en verdad'', ''de veras''. En el período postexílico se convierte en un adversativo decidido: ''pero'', ''sin embargo'', ''no obstante'', introduciendo una matización o concesión. El árabe ''bal'' muestra un rango semántico sorprendentemente paralelo, funcionando tanto como afirmación enfática como adversativo correctivo según el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0065', 'spa', 'Abel-mehola; nombre de lugar que significa ''pradera de la danza'', ciudad en el valle del Jordán', 'Este topónimo hebreo identifica una ciudad en el norte de Israel, probablemente en el valle del Jordán. Su nombre significa ''pradera de la danza''. Abel-mehola aparece en Jueces 7:22 como referencia geográfica durante la huida de los madianitas ante Gedeón. En 1 Reyes 4:12 se ubica dentro de un distrito administrativo de Salomón bajo la jurisdicción de Baana. Su mención más notable es en 1 Reyes 19:16, donde se identifica como la ciudad natal de Eliseo hijo de Safat, a quien Elías debía ungir como su sucesor profético. Su ubicación en las fértiles tierras del valle del Jordán corresponde bien tanto con su nombre como con su importancia administrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0068', 'spa', 'Piedra — roca como material u objeto para construir, lanzar o erigir memoriales; también pesa estándar y, en sentido figurado, título divino.', 'Uno de los sustantivos más concretos y versátiles del hebreo bíblico, אֶבֶן abarca desde la piedra bruta del campo hasta el sillar labrado, pasando por la gema preciosa. Jacob usa una piedra como almohada y después la erige como estela sagrada (Gn 28:11, 18); los enemigos de Israel se hunden ''como una piedra'' en el mar (Ex 15:5); y la ley exige ''piedras'' —es decir, pesas— justas en el comercio (Dt 25:13). El vocablo adquiere fuerza teológica en Génesis 49:24, donde a Dios se lo llama ''la Piedra de Israel,'' metáfora que resuena en toda la tradición multilingüe, desde el árabe حَجَر hasta el alemán der Fels.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0069', 'spa', 'Piedra (arameo); piedra de construcción o piedra sobrenatural, usada en Esdras para el templo y en Daniel para la roca mesiánica.', 'Sustantivo femenino arameo que significa ''piedra'', presente en dos contextos bíblicos de gran dramatismo. En Esdras, el decreto persa especifica ''piedras grandes'' para la reconstrucción del templo de Jerusalén (Esd 5:8; 6:4), situando el término en el mundo práctico de la construcción. En Daniel, la palabra adquiere un significado cósmico: una piedra cortada sin intervención humana golpea la estatua y se convierte en un gran monte que llena toda la tierra (Dn 2:34-35, 45). El español ''piedra'' refleja la simplicidad concreta del vocablo, aun cuando su carga teológica es enorme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0072', 'spa', 'Eben-ezer (Even-haezer); nombre de lugar que significa ''piedra de ayuda'', en memoria de la liberación divina', 'Este topónimo hebreo significa ''piedra de ayuda'' y conmemora el socorro de Dios a Israel. El nombre aparece en dos contextos distintos. En 1 Samuel 4:1 y 5:1, Eben-ezer señala el sitio donde Israel acampó antes de su desastrosa derrota ante los filisteos y la captura del arca. Posteriormente, en 1 Samuel 7:12, tras una gran victoria sobre los filisteos, Samuel erige una piedra y la llama Eben-ezer, declarando: ''Hasta aquí nos ayudó el Señor''. Así, el mismo lugar marca tanto una derrota devastadora como una liberación triunfante, mostrando que es la ayuda de Dios —no el sitio en sí— lo que marca la diferencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0073', 'spa', 'Faja o cinturón sacerdotal tejido, parte de las vestiduras sagradas en el culto israelita.', 'Una faja o cinturón tejido que se ceñía a la cintura como parte de las vestiduras sacerdotales prescritas en la Torá. El אַבְנֵט se menciona exclusivamente en contextos rituales, ciñendo la túnica de lino tanto del sumo sacerdote como de los sacerdotes ordinarios. Josefo lo describe como una banda ancha enrollada varias veces alrededor del pecho, cayendo hasta los pies. Su aparición restringida a textos de la fuente Sacerdotal (Éxodo, Levítico) y un solo pasaje profético (Isa 22:21) subraya su significado sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0074', 'spa', 'Abner — ''mi padre es Ner (una lámpara)''; primo de Saúl y comandante de su ejército', 'Abner (también escrito Aviner en su forma más larga en 1 S 14:50) es un nombre propio masculino que significa ''mi padre es Ner'' o posiblemente ''mi padre es una lámpara,'' evocando el epíteto ''lámpara de Israel'' aplicado a David (2 S 21:17). Fue primo de Saúl y comandante del ejército israelita, desempeñando un papel decisivo en la transición de la casa de Saúl al reinado de David. Tras la muerte de Saúl, Abner instaló a Is-boset como rey rival (2 S 2:8-10), luego se pasó al bando de David antes de ser asesinado a traición por Joab (2 S 3:27). Sus 63 apariciones se concentran en 1-2 Samuel y 1 Reyes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0080', 'spa', 'Polvo fino, partículas en el aire levantadas por viento o pisadas; usado literal y figuradamente del juicio divino.', 'Avaq designa polvo fino o partículas suspendidas en el aire, más ligeras y volátiles que el común afar, que generalmente denota tierra a nivel del suelo. En Éxodo 9:9 describe el hollín fino que Moisés lanza al cielo para desencadenar la plaga de úlceras. Deuteronomio 28:24 advierte que Dios convertirá la lluvia en polvo y ceniza cayendo del cielo. Isaías lo emplea en ambas direcciones: la paja de los malvados se vuelve avaq consumido por la llama (5:24), mientras que los despiadados son reducidos a polvo dispersado por el viento (29:5). Nahúm 1:3 ofrece una imagen impactante: las nubes son el polvo de los pies de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0083', 'spa', 'Pluma de vuelo, ala; las plumas primarias de un ave, símbolo de fuerza y libertad', 'Este sustantivo hebreo designa las plumas de vuelo o alas, específicamente las plumas primarias que permiten volar, y se emplea con frecuencia en sentido poético y metafórico. En el Salmo 55:6, el salmista exclama: ''¡Quién me diera alas como de paloma! Volaría yo y hallaría reposo'', expresando el anhelo de escapar de la angustia. Isaías 40:31 promete que ''los que esperan en el Señor renovarán sus fuerzas; levantarán alas como águilas'', una célebre metáfora del poder divino que fortalece. Ezequiel 17:3 describe a Babilonia como ''un gran águila de grandes alas y largo plumaje'', simbolizando poderío imperial. El término enfatiza fuerza, libertad y movilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0084', 'spa', 'Pluma de vuelo o plumón; las grandes plumas del ala de un ave, usadas poéticamente como imagen de protección divina.', 'Este sustantivo poético designa las grandes plumas de vuelo del ala de un ave, aquellas que le permiten remontarse por los aires. Aparece exclusivamente en pasajes de elevado lirismo, siempre en paralelo con «ala» (כָּנָף), creando una imagen vívida de cobertura protectora. En Deuteronomio 32:11, Dios es comparado a un águila que extiende sus plumas sobre sus polluelos. Salmo 91:4 promete refugio «bajo sus plumas», convirtiendo el plumaje en metáfora del amparo divino. Job 39:13 lo aplica al plumaje del avestruz, contrastando sus vistosas plumas con su incapacidad de volar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0085', 'spa', 'Abram / Abraham — el patriarca, padre de Isaac e Ismael, cuyo nombre fue cambiado por Dios en Génesis 17:5.', 'Abram (''padre exaltado'') aparece desde Génesis 11:26 hasta 17:5, momento en que Dios lo renombra Abraham. El cambio de nombre marca el pacto de la circuncisión y la promesa de una descendencia innumerable (Gn 17:5). Pese a tratarse de dos formas de un mismo nombre, el texto bíblico las presenta como una sola identidad continua: el patriarca que salió de Ur, recibió la promesa de la tierra, engendró a Ismael e Isaac, y llegó a ser el antepasado espiritual reivindicado por el judaísmo, el cristianismo y el islam. Nehemías 9:7 y 1 Crónicas 1:27 conservan la forma original ''Abram'' fuera del Génesis.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0087', 'spa', 'Abram — nombre original del patriarca Abraham antes del cambio de nombre por el pacto', 'Abram (אַבְרָם, ''padre exaltado'') es el nombre de nacimiento del patriarca a quien Dios luego renombró Abraham (''padre de multitudes'') al instituir la circuncisión (Gn 17:5). Las 61 apariciones se concentran en las narrativas tempranas de Abraham en Génesis 11-17, con referencias retrospectivas en 1 Crónicas 1:27 y Nehemías 9:7. El cambio de nombre tiene una carga teológica profunda: Abram designa al hombre antes del pacto de la circuncisión; Abraham, al socio del pacto con Dios que sería padre de muchas naciones. El juego etimológico de Génesis 17:5 constituye uno de los momentos de nombramiento más memorables de toda la Biblia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0088', 'spa', 'Obot, topónimo que significa ''odres''; estación del peregrinaje de Israel por el desierto, en la frontera oriental de Edom.', 'Un campamento en el desierto cuyo nombre probablemente deriva de la palabra hebrea para odres o recipientes de cuero, lo que sugiere un lugar donde se almacenaba o se encontraba agua. Obot aparece en dos pasajes itinerarios que trazan la ruta de Israel desde Egipto hasta Canaán. En Números 21:10-11 los israelitas viajan de Obot a Iye-abarim, en la frontera de Moab. Números 33:43-44 registra la misma parada en el listado completo del recorrido. Su ubicación exacta sigue siendo incierta, aunque generalmente se sitúa en los márgenes orientales de Edom, en algún punto de la región del Arabá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0090', 'spa', 'Agag; rey amalecita perdonado por Saúl y ejecutado por Samuel, también invocado en el oráculo de Balaam como símbolo de poder real.', 'Nombre propio del rey de Amalec, figura central en una de las confrontaciones más dramáticas del Antiguo Testamento. Balaam lo invoca primero en su oráculo, profetizando que el rey de Israel será «más alto que Agag» (Nm 24:7), usando el nombre como sinónimo de poder real formidable. El núcleo narrativo se encuentra en 1 Samuel 15, donde Saúl captura vivo a Agag pero lo perdona desobedeciendo el mandato divino, lo que provoca la severa reprensión de Samuel y el anuncio del rechazo de Saúl como rey. Samuel ejecuta personalmente a Agag (1 S 15:33). El nombre resuena después en Ester a través de «Amán el agagueo», sugiriendo un vínculo genealógico o tipológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0091', 'spa', 'Agagueo -- gentilicio que identifica la ascendencia de Amán, vinculándolo posiblemente con el rey amalecita Agag', 'Agagueo es el adjetivo gentilicio aplicado exclusivamente a Amán, el antagonista del libro de Ester. Las cinco apariciones (Est 3:1, 10; 8:3, 5; 9:24) funcionan como epíteto: «Amán el agagueo», identificándolo por su origen ancestral o étnico. La tradición judía y Josefo vinculan esta designación con Agag, el rey amalecita perdonado por Saúl (1 Sam 15), convirtiendo así la narrativa de Ester en una continuación del antiguo conflicto entre Israel y Amalec. En español se emplea la forma «agagueo» con un sufijo gentilicio reconocible, al igual que el francés «Agaguite» y el alemán «Agagiter».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0092', 'spa', 'Manojo, atadura, tropa o bóveda; algo atado o reunido formando una unidad.', 'Sustantivo construido sobre la idea raíz de atar o reunir, que aparece en cuatro contextos marcadamente distintos pero unidos por la noción de cosas sujetas entre sí. En Éxodo 12:22 designa un manojo de hisopo usado para aplicar la sangre de la Pascua. Isaías 58:6 lo emplea metafóricamente para las ataduras de la opresión. En 2 Samuel 2:25 describe una tropa de combatientes reagrupados. Y de forma más evocadora, Amós 9:6 habla de la bóveda celeste de Dios, como si el cielo mismo fuera una estructura ensamblada y unida por la destreza divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0098', 'spa', 'Estanque, laguna o cuerpo de agua estancada; por extensión, pantano o ciénaga.', 'Designa un cuerpo de agua quieta y acumulada: un estanque, una laguna o un pantano. En los relatos de las plagas de Egipto, los estanques (אֲגַמִּים) son golpeados junto con los ríos y canales (Éx 7:19; 8:5). Los profetas emplean la imagen con gran fuerza: Dios transforma la tierra seca en estanque de aguas (Sal 107:35; Is 41:18), mientras que la ruina de Babilonia se convierte en pantanos estancados (Is 14:23). La palabra conlleva un matiz atmosférico: no se trata de manantiales cristalinos sino de aguas reunidas, a veces turbias, lo que explica que la misma raíz pueda deslizarse hacia el significado de pantano o ciénaga en contextos como Ezequiel 47:11.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0100', 'spa', 'Junco, espadaña -- planta palustre usada para hacer cuerdas y como figura de lo humilde o insignificante', 'אַגְמוֹן designa un junco o espadaña, una planta alta de pantano bien conocida en todo el antiguo Cercano Oriente. En sentido literal, aparece en los discursos de Dios a Job: las fibras retorcidas del junco sirven como cuerda (Job 41:2) y los juncos secos arden como combustible (Job 41:20). Isaías emplea la imagen de inclinar la cabeza como un junco para criticar el ayuno vacío (Is 58:5). Metafóricamente, el junco representa lo humilde e insignificante en los oráculos de juicio de Isaías: «palmera y junco» como merismo de lo alto y lo bajo (Is 9:14; 19:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0101', 'spa', 'Tazón, vasija; recipiente para contener líquidos, usado en contextos rituales y domésticos', 'Este sustantivo hebreo designa un tazón o vasija, un recipiente curvado para contener líquidos u otros contenidos. En Éxodo 24:6, Moisés emplea vasijas para recoger la sangre durante la ceremonia del pacto en el Sinaí, rociando la mitad sobre el altar y la otra mitad sobre el pueblo. Cantar de los Cantares 7:2 utiliza una imagen sensual: ''Tu ombligo es como una copa redonda que nunca le falta vino'', comparando la belleza de la amada con la plenitud de un tazón. Isaías 22:24 emplea el término metafóricamente para describir los descendientes de Eliaquim como vasijas de diverso tamaño. La palabra abarca tanto recipientes rituales como domésticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0102', 'spa', 'Bandas, hordas o tropas militares que acompañan a un líder; fuerzas armadas en el séquito de un ejército.', 'El sustantivo אֲגַף designa bandas u hordas de fuerzas combatientes, empleado exclusivamente en los oráculos de Ezequiel. Es un préstamo del acadio agappu (''ala''), originalmente referido al ala de un ejército, y su uso en Ezequiel siempre describe el séquito militar de reyes e invasores. Las vastas hordas de Gog (Ez 38:9, 22; 39:4), las tropas de Gomer y Bet-togarmá (Ez 38:6), y las fuerzas dispersas del rey de Judá (Ez 12:14; 17:21) son todas designadas con esta palabra. El español «tropas» y «hordas» capturan bien el sentido de fuerzas militares masivas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0103', 'spa', 'Recoger, cosechar; recolectar cultivos o alimentos, especialmente en contexto agrícola', 'Este verbo hebreo significa recoger o recolectar, particularmente en contextos agrícolas de cosecha. Deuteronomio 28:39 advierte a Israel con una maldición de futilidad: ''Plantarás viñas y las cultivarás, pero no beberás del vino ni recogerás las uvas, porque los gusanos se las comerán''. Proverbios 6:8 elogia a la hormiga, que ''recoge su alimento en la cosecha'', como ejemplo de preparación diligente. Proverbios 10:5 contrasta al hijo sabio ''que recoge en el verano'' con el hijo que deshonra al dormir durante la siega. El verbo enfatiza la recolección deliberada, especialmente de productos agrícolas, como parte de una mayordomía prudente y un trabajo oportuno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0104', 'spa', 'carta, epistola (arameo); correspondencia oficial escrita en contextos administrativos persas', 'Este sustantivo arameo designa una carta o epistola, especialmente correspondencia oficial dentro de la administracion imperial persa. Sus tres apariciones se encuentran en Esdras, describiendo comunicaciones dirigidas a la corte persa o provenientes de ella en relacion con la reconstruccion de Jerusalen. Esdras 4:8 menciona una carta escrita contra Jerusalen por Rehum y Simsai al rey Artajerjes. Esdras 4:11 presenta la copia de la carta enviada con acusaciones contra los judios. Esdras 5:6 registra la carta de Tatnai al rey Dario solicitando instrucciones sobre la reconstruccion del templo. Estas cartas oficiales moldearon el destino politico de los exiliados que regresaban.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0107', 'spa', 'El sustantivo אִגֶּרֶת (iggeret) designa una carta o epístola formal, apareciendo exclusivamente en la literatura postexílica (Crónicas, Esdras-Nehemí', 'El sustantivo אִגֶּרֶת (iggeret) designa una carta o epístola formal, apareciendo exclusivamente en la literatura postexílica (Crónicas, Esdras-Nehemías, Ester). Es un préstamo del acadio egirtu (''carta, documento''), reflejando el vocabulario administrativo del período persa que impregna estos libros. Ezequías envía cartas por todo Israel y Judá convocando al pueblo a la Pascua (2 Cr 30:1, 6). Nehemías obtiene cartas del rey Artajerjes otorgándole salvoconducto y derechos de madera (Neh 2:7-9; 6:5, 17, 19). En Ester, el término adquiere un peso de vida o muerte: las cartas de Amán decretan el genocidio (Est 9:26, 29), y las contracartas de Mardoqueo establecen Purim.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0113', 'spa', 'Señor, amo, soberano — título de autoridad para superiores humanos, propietarios, Dios como gobernante supremo o señores en plural.', 'Título hebreo fundamental de autoridad y respeto, אָדוֹן expresa la relación entre un subordinado y quien detenta poder sobre él. En la vida social cotidiana servía como tratamiento deferente hacia reyes, esposos y jefes militares, de modo análogo al árabe سَيِّدِي o al honorífico coreano 주인. Cuando se aplica a Dios, adquiere un peso teológico que los masoretas señalaron mediante una vocalización especial (Adonai), distinguiendo la soberanía divina del mero rango humano. La forma plural a veces intensifica el singular para expresar majestad suprema, mientras que otras veces simplemente denota múltiples gobernantes o amos que comparten autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0116', 'spa', 'Entonces, en aquel momento — adverbio temporal arameo que marca acción secuencial o consecuente', 'El adverbio arameo אֱדַיִן (''entonces, en aquel momento'') es el principal conector temporal del arameo bíblico, hilvanando la lógica narrativa de Esdras y Daniel. Marca secuencia consecuente: se emite un decreto y entonces los funcionarios actúan (Esd 4:23-24); se plantea una pregunta y entonces llega una respuesta (Dn 2:14-15). En las narrativas cortesanas de Daniel, אֱדַיִן puntúa los momentos de crisis y resolución: ''entonces Daniel respondió con prudencia y sabiduría'' (Dn 2:14), ''entonces el rey promovió a Daniel'' (Dn 2:48). Su consistente fuerza temporal a lo largo de las 57 apariciones lo convierte en el equivalente arameo del hebreo אָז.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0117', 'spa', 'majestuoso, poderoso; noble — describe grandeza en la naturaleza, en Dios o en gobernantes; como sustantivo, un noble o líder', 'majestuoso, poderoso; noble — describe grandeza en la naturaleza, en Dios o en gobernantes; como sustantivo, un noble o líder');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0119', 'spa', 'Verbo de color cuyo significado depende de la voz y el tronco verbal. En el Pu''al (pasivo) describe un proceso de teñido externo: pieles de carnero ''t', 'Verbo de color cuyo significado depende de la voz y el tronco verbal. En el Pu''al (pasivo) describe un proceso de teñido externo: pieles de carnero ''teñidas de rojo'' para la cubierta del Tabernáculo, repetido siete veces en las narraciones de construcción del Éxodo (25:5; 26:14; 35:7, 23; 36:19; 39:34). En los troncos activo y estativo describe rojez inherente: la belleza rubicunda de los nazareos antes del asedio (Lm 4:7), el enrojecimiento del vino como advertencia contra la embriaguez (Pr 23:31) y la mancha escarlata del pecado que Dios puede hacer blanca como la nieve (Is 1:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0120', 'spa', 'Hombre, ser humano; humanidad colectivamente; también el nombre propio Adán.', 'El hebreo אָדָם cubre un abanico notablemente amplio: desde un individuo concreto (''un hombre'') hasta la especie humana entera (''la humanidad''), pasando por el nombre propio del primer ser humano. A diferencia de אִישׁ, que destaca a la persona masculina en contraste con la mujer, אָדָם subraya a la criatura como tal: mortal, nacida de la tierra, hecha a imagen de Dios. El vínculo etimológico con אֲדָמָה (''suelo, tierra'') resuena a lo largo de toda la Escritura, desde Génesis 2:7, donde Dios forma al hombre del polvo de la tierra, hasta las reflexiones del Eclesiastés sobre la mortalidad humana. El árabe conserva el mismo espectro: آدَم como nombre propio, إِنْسَان para el ser humano genérico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0121', 'spa', 'Uno de los nombres más resonantes de las Escrituras, con doble función como nombre propio de persona y topónimo. Como persona, Adán es el primer ser h', 'Uno de los nombres más resonantes de las Escrituras, con doble función como nombre propio de persona y topónimo. Como persona, Adán es el primer ser humano creado por Dios, central en la narrativa del Génesis sobre los orígenes, la caída y las genealogías que trazan la descendencia de la humanidad (Gn 3:17; 5:1-5; 1 Cr 1:1). El nombre mismo es un juego de palabras con ''adamah'' (tierra), de la cual Dios lo formó. En Oseas 6:7, ''como Adán'' evoca la ruptura del pacto. Como lugar, Adán es la ciudad junto a Saretán donde las aguas del Jordán se detuvieron formando un montón durante el cruce de Israel (Jos 3:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0122a', 'spa', 'Rojo, rojizo; adjetivo de color que describe tonalidades rojizas en piel, animales, agua o vestiduras.', 'El adjetivo אָדֹם significa ''rojo'' o ''rojizo'', aplicado a una variedad de descripciones físicas. Retrata la tez del amado como saludable y atractiva (Cnt 5:10, ''mi amado es blanco y rubicundo''), especifica la vaca alazana sin defecto requerida para los ritos de purificación (Nm 19:2), y describe agua que pareció roja como sangre a los moabitas (2 R 3:22). Isaías lo emplea para las manchas carmesíes en las vestiduras del guerrero divino (Is 63:2), mientras que las visiones de Zacarías incluyen caballos rojos (Zac 1:8). El español «rojo» y «rojizo» reflejan fielmente el sentido cromático vívido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0123', 'spa', 'Edom — sobrenombre de Esaú que significa ''rojo,'' y por extensión la nación, el territorio y el pueblo descendiente de él al sureste del Mar Muerto.', 'Edom funciona simultáneamente como nombre personal de Esaú y como designación de sus descendientes y su territorio en las escarpadas tierras altas al sureste del Mar Muerto. La etimología está anclada en Génesis 25:30, donde Esaú suplica por ''ese guiso rojo'' (הָאָדֹם) y recibe el apodo. A lo largo de sus 100 ocurrencias, el nombre abarca al patriarca mismo (Gn 36:1, 8), a la nación colectivamente (Nm 20:18-21; 2 S 8:14) y a la tierra como entidad geográfica (Gn 32:3; Jer 49:17). La literatura profética convierte a Edom en tipo de la oposición hostil al pueblo de Dios: todo el oráculo de Abdías va dirigido contra Edom, y Malaquías 1:4 presenta su desolación como prueba del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0124', 'spa', 'cornerina, rubi; piedra preciosa de color rojo, posiblemente sardio', 'Este sustantivo hebreo designa una piedra preciosa de color rojo, traducida tradicionalmente como ''rubi'' o ''cornerina,'' aunque su identificacion exacta es incierta. El nombre deriva de su tonalidad rojiza (de la raiz que significa ''ser rojo''). En Exodo 28:17 y 39:10 es la primera piedra de la primera hilera del pectoral del sumo sacerdote, representando una de las doce tribus de Israel. Ezequiel 28:13 la incluye entre las piedras preciosas que adornaban al rey de Tiro en Eden, el jardin de Dios, evocando un esplendor primigenio. Su tono rojizo la hacia muy apreciada en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0125', 'spa', 'Rojizo, de tinte rojizo; usado exclusivamente para el color de erupciones cutáneas en la ley diagnóstica levítica.', 'Adjetivo reduplicativo derivado de la raíz אדם (''ser rojo''), que describe un matiz rojizo en las lesiones cutáneas. Todas sus apariciones se encuentran en Levítico 13-14, dentro de las instrucciones sacerdotales para diagnosticar enfermedades de la piel. La palabra capta una decoloración ambigua, no completamente roja, que los sacerdotes debían evaluar cuidadosamente. Las traducciones en diversos idiomas lo vierten consistentemente como ''rojizo'' (francés rougeâtre, español rojiza), reflejando la fuerza diminutiva o aproximativa de la reduplicación hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0126', 'spa', 'Admá -- ciudad del valle de Sidim, destruida junto con Sodoma y Gomorra', 'Admá fue una de las cinco «ciudades de la llanura» en el valle de Sidim, mencionada junto a Sodoma, Gomorra, Zeboim y Zoar. Sus cinco apariciones trazan un arco narrativo: primero en la Tabla de las Naciones como ciudad fronteriza cananea (Gn 10:19), luego en la alianza de reyes derrotados por la coalición oriental (Gn 14:2, 8), y finalmente como sinónimo de juicio divino. Deuteronomio 29:23 nombra a Admá junto con Sodoma al describir la devastación de la maldición del pacto, y Oseas 11:8 -- «¿Cómo podré hacerte como Admá?» -- revela la angustiada reluctancia de Dios a destruir a Efraín como destruyó esta antigua ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0127', 'spa', 'Tierra, suelo, terreno; tierra cultivable, patria, territorio; sustancia física de la que fue formada la humanidad.', 'Adamah es la tierra que da nombre a adam (la humanidad), un juego de palabras ya presente en la creación (Gn 2:7). Designa primero la tierra fértil y cultivable que produce fruto al ser labrada (Gn 2:5; 3:17), y luego se amplía para significar patria o territorio nacional, como en la fórmula de la alianza ''la adamah que YHWH tu Dios te da'' (Dt 7:13). El arco teológico es notable: la humanidad es tomada de la adamah, maldecida sobre ella, exiliada de ella y finalmente recibe la promesa de restauración a ella.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0130', 'spa', 'Edomí — edomita; persona perteneciente a Edom, la nación descendiente de Esaú, al este y sur del mar Muerto. El gentilicio אֲדֹמִי (''edomita'') designa', 'Edomí — edomita; persona perteneciente a Edom, la nación descendiente de Esaú, al este y sur del mar Muerto. El gentilicio אֲדֹמִי (''edomita'') designa a una persona de la nación de Edom, el territorio al sureste del mar Muerto colonizado por los descendientes de Esaú (Gn 36). A pesar de la enemistad entre Israel y Edom, la Torá ordena: «No aborrecerás al edomita, porque es tu hermano» (Dt 23:7). El término se aplica de manera más memorable a Doeg el edomita, jefe de los pastores de Saúl, quien delató a los sacerdotes de Nob (1 S 21:7; 22:9, 18; título del Sal 52). También aparece en referencia a las mujeres edomitas entre las esposas extranjeras de Salomón (1 R 11:1) y a los edomitas como enemigos en la historia de Hadad (1 R 11:14-17). Las doce apariciones denotan la misma identidad étnica, variando solo en número y género.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0132', 'spa', 'rojo, rojizo; de tez rubicunda o coloracion saludable', 'Este adjetivo hebreo significa rojo o rojizo, describiendo una tez rubicunda o coloracion saludable. Genesis 25:25 describe a Esau al nacer: ''Salio el primero rojizo, todo cubierto como de un manto de pelo,'' y su color dio origen al nombre Edom (rojo). En 1 Samuel 16:12 se describe al joven David como ''rubio, de hermosos ojos y buena presencia,'' retrato de salud y vigor juvenil. En 1 Samuel 17:42 se nota la misma tez cuando Goliat lo ve por primera vez. En el antiguo Cercano Oriente, una tez rojiza indicaba salud, vitalidad y atractivo. El termino puede denotar color rojo literal o el rubor saludable de la juventud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0134', 'spa', 'Basa, pedestal; base metálica del Tabernáculo; en sentido amplio, fundamento o cimiento de una estructura', 'Designa la basa o pedestal metálico en el que se insertaban las tablas y columnas verticales del Tabernáculo, típicamente fundido en plata o bronce. La gran mayoría de sus 57 apariciones se concentra en los textos de construcción del Tabernáculo en Éxodo y Números, donde pares de basas anclan cada tablón. Fuera de este uso técnico, aparece en dos memorables pasajes poéticos: Job 38:6 pregunta quién hundió los cimientos (אַדְנֵי) de la tierra, y Cantares 5:15 describe las piernas del amado como columnas asentadas sobre pedestales de oro fino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0136', 'spa', 'Señor, amo: como título divino (Adonai, Señor Dios) y como tratamiento respetuoso a un superior humano.', 'Adon es una de las palabras de mayor peso teológico en la Biblia hebrea. En su uso abrumadoramente dominante, funciona como título divino Adonai (''mi Señor''), el sustituto oral del Tetragrama YHWH, que expresa la soberanía de Dios y su relación personal de alianza con Israel (Gn 15:2, ''Oh Señor YHWH''). La vocalización masorética distingue deliberadamente la referencia divina de la humana. En un puñado de pasajes conserva su significado secular más antiguo de ''señor'' o ''amo,'' dirigiéndose a un superior humano con deferencia (Jos 3:11; Jue 6:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0137', 'spa', 'Adoni-bezec; nombre propio o titulo que significa ''senor de Bezec,'' un rey cananeo', 'Este nombre hebreo designa a un rey cananeo derrotado por las tribus de Juda y Simeon. El nombre significa ''senor de Bezec,'' combinando ''Adoni'' (mi senor) con ''Bezec'' (el nombre de la ciudad). Jueces 1:5-7 narra el encuentro: Israel derrota a Adoni-bezec, le corta los pulgares de manos y pies, y el confiesa haber hecho lo mismo a setenta reyes. Muere en Jerusalen. Algunos eruditos sugieren enmendar el nombre a ''Adoni-sedec'' (senor de justicia), vinculandolo al rey de Jerusalen en Josue 10, pero el texto presenta a Adoni-bezec como un gobernante distinto cuya mutilacion de enemigos vencidos recibe justicia poetica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0138', 'spa', 'Adonías (''mi Señor es Yahvé''); principalmente el cuarto hijo de David que disputó la sucesión de Salomón, además de otras dos figuras bíblicas.', 'Adonías (''mi Señor es Yahvé''); principalmente el cuarto hijo de David que disputó la sucesión de Salomón, además de otras dos figuras bíblicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0140', 'spa', 'Adonicam; nombre propio que significa ''mi Senor se ha levantado'' o ''el Senor se alzo''', 'Este nombre propio hebreo significa ''mi Senor se ha levantado'' o ''el Senor se ha puesto en pie,'' un nombre teoforico que expresa fe en la accion divina. Adonicam fue cabeza de una familia que regreso del exilio babilonico. Esdras 2:13 enumera 666 (o 667) descendientes de Adonicam entre los que retornaron con Zorobabel. Esdras 8:13 menciona miembros posteriores ''de los hijos de Adonicam'' que vinieron con Esdras, incluyendo a Elifelet, Jeiel y Semaias. Nehemias 7:18 confirma la inclusion de esta familia en la comunidad restaurada. El nombre da testimonio de la fe en que el Senor actuaria para restaurar a su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0142', 'spa', 'majestuoso, glorioso; que posee esplendor, honra o condición exaltada', 'Este adjetivo o forma verbal hebrea significa majestuoso, glorioso o hecho glorioso. Aparece en contextos que celebran la majestad y el poder de YHWH. Éxodo 15:6 exalta: «Tu diestra, oh Señor, ha sido satisfecha en poder», celebrando la victoria en el mar Rojo. Éxodo 15:11 pregunta retóricamente: «¿Quién como tú, glorioso en santidad, temible en alabanzas, hacedor de maravillas?», un reconocimiento hímnico de la gloria incomparable de Dios. Isaías 42:21 afirma que el Señor engrandecerá la ley y la hará gloriosa. El término transmite un esplendor divino que inspira reverencia y adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0143', 'spa', 'Adar; duodécimo mes del calendario hebreo (febrero–marzo), el mes de Purim en el libro de Ester.', 'Nombre del duodécimo mes en el calendario hebreo postexílico, tomado del babilónico «Addaru» y correspondiente aproximadamente a febrero–marzo. Las ocho apariciones del término se encuentran en el libro de Ester, donde Adar es el mes escogido por la suerte de Amán para el exterminio de los judíos (Est 3:7, 13) y, posteriormente, el mes de su liberación y la celebración de Purim (Est 9:1, 15, 17, 19, 21). El nombre se translitere de manera idéntica en todos los idiomas de destino, reflejando su condición de préstamo lingüístico incluso en el hebreo original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0152', 'spa', 'Adramelec; nombre de una deidad y de una persona, que significa ''Adar es príncipe'' o ''Adar es rey''', 'Este nombre hebreo aparece en dos contextos distintos. Primero, Adramelec era una deidad adorada por los habitantes de Sefarvaim, a quienes quemaban a sus hijos en sacrificio (2 Reyes 17:31), una práctica aborrecida por YHWH. Segundo, Adramelec fue un hijo del rey asirio Senaquerib que, junto con su hermano Sarezer, asesinó a su padre en el templo de Nisroc y huyó a Ararat (2 Reyes 19:37; Isaías 37:38). El nombre deriva del dios asirio Adar combinado con «melek» (rey/príncipe). Ya sea deidad o persona, el nombre conlleva asociaciones de religión pagana y violencia: sacrificio infantil en un caso, parricidio en el otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0154', 'spa', 'Edrei; ciudad principal de Basán donde Israel derrotó al rey Og, también una ciudad en el territorio de Neftalí.', 'Topónimo que identifica una ciudad principal del reino de Basán en Transjordania, la actual Der''a en el sur de Siria. Edrei es el lugar donde Moisés e Israel libraron la batalla decisiva contra el rey Og (Nm 21:33; Dt 3:1), una victoria recordada repetidamente en Deuteronomio y Josué como evidencia de la fidelidad de Dios. La ciudad se empareja con Astarot como una de las dos residencias reales de Og (Dt 1:4; Jos 12:4; 13:12, 31). Otra Edrei distinta aparece en Josué 19:37 como ciudad asignada a Neftalí. El nombre se translitere de manera uniforme en todos los idiomas, conservando su forma semítica antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0155', 'spa', 'Manto exterior grande, capa o capa; en sentido figurado, gloria, majestad o esplendor. Conocido sobre todo como el manto profético — la vestidura que ', 'Manto exterior grande, capa o capa; en sentido figurado, gloria, majestad o esplendor. Conocido sobre todo como el manto profético — la vestidura que Elías llevaba y echó sobre Eliseo como señal de sucesión (1 R 19:19), y que abrió el Jordán al golpear el agua (2 R 2:8, 14). La palabra también designa el costoso manto babilónico que tentó a Acán en Jericó (Jos 7:21). En la poesía profética, sin embargo, la misma palabra se desplaza hacia el esplendor abstracto: la vid en Ezequiel 17:8 produce ramas «magníficas», y Zacarías 11:3 lamenta la pérdida de la «gloria» de los pastores, donde vestidura y grandeza se fusionan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0157', 'spa', 'Amar; como participio: amante, amigo, amante ilícito; pasivo: amado/a; también el sustantivo abstracto ''amor'' (ahavah).', 'El verbo principal de amor en la Biblia hebrea abarca desde la ternura más íntima hasta la acusación profética más feroz. Jacob amó a Raquel (Gn 29:18), el gran mandamiento exige amar a Dios con todo el corazón (Dt 6:5), pero la misma raíz en el intensivo Piel se convierte en arma de los profetas: Oseas y Jeremías lanzan מְאַהֲבַיִךְ (''tus amantes'') contra el Israel infiel. El participio pasivo produce ''amada,'' la esposa favorecida de Dt 21. El sustantivo abstracto אַהֲבָה designa el amor mismo como cualidad o estado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0160', 'spa', 'Amor, afecto, devoción — como sustantivo abstracto o infinitivo verbal que expresa el acto y la actitud de amar', 'Amor, afecto, devoción — como sustantivo abstracto o infinitivo verbal que expresa el acto y la actitud de amar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0162', 'spa', '!Ay! !Ah! — exclamacion de dolor, consternacion o suplica desesperada. אֲהָהּ es uno de los sonidos mas crudos de la Biblia hebrea — un grito gutural ', '!Ay! !Ah! — exclamacion de dolor, consternacion o suplica desesperada. אֲהָהּ es uno de los sonidos mas crudos de la Biblia hebrea — un grito gutural que irrumpe en momentos de conmocion, dolor o suplica. Jefté lo exclama al ver a su hija (Jue 11:35); el siervo de Eliseo lo grita cuando la cabeza del hacha se hunde en el Jordan (2 R 6:5). De manera mas caracteristica aparece en la formula אֲהָהּ אֲדֹנָי יְהוִה (''!ay, Señor DIOS!''), una expresion de angustia profética usada por Josué (7:7), Gedeón (Jue 6:22), Jeremías y Ezequiel. Joel la intensifica con אֲהָהּ לַיּוֹם, ''!ay de aquel dia!'' (1:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0163', 'spa', 'Ahava; nombre de lugar que designa una ciudad o río en Babilonia donde se reunieron los exiliados', 'Este topónimo hebreo designa tanto una ciudad como un río (o canal) en Babilonia donde Esdras reunió a los exiliados que regresaban. Esdras 8:15 relata: «Los reuní junto al río que fluye hacia Ahava, y acampamos allí tres días.» Este punto de encuentro permitió a Esdras revisar la compañía y descubrir que no había levitas, lo que le llevó a enviar por ellos. Esdras 8:21 señala que Esdras proclamó un ayuno «allí junto al río Ahava», buscando la protección divina para el peligroso viaje. Esdras 8:31 registra su partida «desde el río Ahava» hacia Jerusalén. El lugar sirvió como base de preparación espiritual antes del regreso a casa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0164', 'spa', 'Ehud, juez benjaminita que liberó a Israel de la opresión moabita; también un descendiente de Bilhán.', 'Nombre propio que llevan dos personajes benjaminitas en la Biblia hebrea. El Ehud más destacado es el juez zurdo de Jueces 3:15-30, quien asesinó al rey moabita Eglón con una espada corta oculta, liberando así a Israel de dieciocho años de sometimiento. Su relato constituye uno de los episodios narrativos más vívidos del libro de Jueces, lleno de ironía y detalle físico. Un segundo Ehud aparece en 1 Crónicas 7:10 como hijo de Bilhán, posiblemente un eco genealógico del mismo héroe tribal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0165', 'spa', '¿dónde? (partícula interrogativa relacionada con אֵי y אַיֵּה, usada en desafío profético)', 'Esta rara partícula interrogativa aparece únicamente en Oseas 13:10, 14, donde Dios desafía a Israel sobre el destino de su rey y la ubicación del aguijón de la muerte. Las versiones antiguas (Septuaginta, Siríaca, Vulgata, Targum) y la mayoría de los eruditos modernos la interpretan como «¿dónde?», una pregunta de tono burlón. Algunos intérpretes antiguos la tomaron como verbo en primera persona «yo seré», pero el contexto y la forma yusiva favorecen la lectura interrogativa. La cita de Pablo en 1 Corintios 15:55 («¿Dónde está, oh muerte, tu aguijón?») confirma el sentido interrogativo, transformando el oráculo de juicio de Oseas en un triunfo de resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0167', 'spa', 'plantar tienda, acampar; establecer morada al estilo nómada', 'Este verbo hebreo significa plantar una tienda o acampar, reflejando el estilo de vida nómada de los antepasados de Israel. Génesis 13:12 declara que «Lot plantó sus tiendas hasta Sodoma», una decisión fatídica que lo acercó a la maldad. Génesis 13:18 relata que «Abram movió su tienda y fue a habitar junto a los encinos de Mamre, que están en Hebrón, y edificó allí altar al Señor», mostrando la adoración itinerante de Abraham. Isaías 13:20 profetiza la desolación de Babilonia: «Nunca más será habitada... ni el árabe plantará allí tienda», usando la ausencia de tiendas como señal de devastación total. El verbo capta la existencia transitoria y móvil de los pastores nómadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0168', 'spa', 'Tienda; morada portátil de tela o pieles, usada como vivienda nómada, lugar de culto (el Tabernáculo) y campamento militar.', 'Una de las palabras más evocadoras de la Biblia hebrea, ohel conjura todo el mundo de la vida patriarcal y del desierto. Desde Jabal, ''padre de los que habitan en tiendas'' (Gn 4:20), pasando por la elaborada Tienda de Reunión donde la presencia de Dios moraba en medio de Israel, hasta la imagen romántica de las tiendas oscuras del Cantar de los Cantares (1:5), esta palabra aparece cerca de 350 veces. Cada lengua principal la traduce con un equivalente estable: árabe خيمة, alemán Zelt, francés tente, subrayando su significado concreto y uniforme a través de las culturas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0170', 'spa', 'Oholah -- nombre simbólico de Samaria como mujer infiel en la alegoría de Ezequiel', 'Oholah es un nombre propio simbólico creado por el profeta Ezequiel para personificar a Samaria (el reino del norte) como una mujer adúltera. El nombre significa ''la que tiene su propia tienda'', insinuando que Samaria estableció un culto ilegítimo aparte del templo de Jerusalén: ''su tienda'' en lugar de la de Dios. Las cinco apariciones se hallan en Ezequiel 23, la extensa alegoría de dos hermanas — Oholah (Samaria) y Oholibah (Jerusalén) — que se prostituyeron con Asiria y Babilonia respectivamente. Las traducciones multilingües — ''Oholah'' en inglés, ''Ohola'' en español y francés — transliteran directamente el nombre, preservando su carga simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0171', 'spa', 'Oholiab -- artesano principal que asistió a Bezaleel en la construcción del tabernáculo', 'Oholiab fue un artesano de la tribu de Dan a quien Dios designó como asistente principal de Bezaleel para la construcción del tabernáculo en el desierto (Éx 31:6). Su nombre significa ''la tienda del padre'', una designación muy apropiada para quien fue encargado de edificar la morada de Dios entre Israel. Sus cinco apariciones se encuentran en Éxodo (31:6; 35:34; 36:1-2; 38:23), siempre en el contexto de la construcción del tabernáculo. Se le describe como hábil en grabado, diseño y bordado, complementando el trabajo de Bezaleel en metales y madera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0172', 'spa', 'Oholiba, nombre simbólico de Jerusalén como esposa infiel en la alegoría de Ezequiel sobre las dos hermanas.', 'Nombre profético propio que significa ''mi tienda está en ella'', usado por Ezequiel para representar a Jerusalén junto a su hermana Oholá (Samaria). El nombre sugiere que la presencia del tabernáculo de Dios habitaba en Jerusalén, lo cual hace su infidelidad tanto más grave. Las seis apariciones se concentran en Ezequiel 23, una de las alegorías más vívidas de las Escrituras sobre la infidelidad al pacto. La etimología del nombre vincula la tienda (אֹהֶל) de la morada de Dios con la ciudad que debía albergarlo fielmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0173', 'spa', 'Oholibama — esposa de Esaú y jefa de un clan edomita, cuyo nombre significa ''tienda del lugar alto''.', 'Oholibama (cuyo significado es ''tienda del lugar alto'') aparece exclusivamente en las genealogías de Esaú en Génesis 36 y 1 Crónicas 1. Se la identifica como hija de Aná y esposa de Esaú, a través de quien varios clanes edomitas trazaron su linaje. El nombre también puede designar a un jefe o clan edomita. Las versiones en distintos idiomas son notablemente uniformes —en español ''Oholibama'', en francés y alemán formas similares— conservando la forma hebrea, como es habitual en el tratamiento de nombres propios en la traducción bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0174', 'spa', 'Áloes; árbol aromático o la especia fragante que se obtiene de él.', 'Se refiere a un árbol aromático o a su producto fragante, tradicionalmente identificado con la madera de áloe (aloexylon agallochum), apreciada en todo el antiguo Cercano Oriente por su perfume. En el oráculo de Balaam, las tiendas de Israel se comparan con áloes plantados por el Señor junto a corrientes de agua (Nm 24:6). En otros pasajes aparece junto a la mirra y la casia como perfume de lujo: ungiendo vestiduras reales (Sal 45:8), perfumando el lecho de una amante (Pr 7:17) y enumerado entre las especias más selectas del jardín en Cantares 4:14.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0175', 'spa', 'Aarón; hermano mayor de Moisés, primer sumo sacerdote de Israel y ancestro del sacerdocio levítico.', 'Aharon (Aarón) aparece 347 veces, lo que lo convierte en una de las figuras nombradas con más frecuencia en la Biblia hebrea. Como hermano mayor de Moisés (Ex 7:7), sirvió de portavoz ante el Faraón y fue consagrado como primer sumo sacerdote de Israel (Ex 28-29). Su nombre domina la fuente Sacerdotal en Éxodo, Levítico y Números, donde ''Aarón y sus hijos'' se vuelve una designación formulaica del sacerdocio legítimo. La narrativa no es acrítica: Aarón también fabricó el becerro de oro (Ex 32) y fue excluido de entrar en la Tierra Prometida junto con Moisés (Nm 20:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0176a', 'spa', 'O — conjunción disyuntiva que presenta alternativas o introduce casos particulares.', 'La conjunción hebrea אוֹ funciona como la disyuntiva estándar ''o,'' conectando alternativas en códigos legales, narrativas y habla cotidiana. A lo largo de sus 320 ocurrencias abarca desde simples opciones de uno u otro tipo (Gn 24:49) hasta la fórmula legal técnica ''o si'' que introduce subcasos dentro de una norma general (Ex 21:31; Lv 4:23). También puede implicar preferencia —''o más bien''— como en Gn 24:55. Cada lengua principal la traduce con una sola palabra básica: francés ''ou,'' alemán ''oder,'' confirmando su función universal y estable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0178', 'spa', 'Espíritu de un muerto consultado mediante la necromancia; también un odre o recipiente de cuero para almacenar vino. En casi todas sus apariciones, es', 'Espíritu de un muerto consultado mediante la necromancia; también un odre o recipiente de cuero para almacenar vino. En casi todas sus apariciones, esta palabra se refiere a un médium o espíritu nigromante, el tipo de práctica de conjuración severamente prohibida en toda la Torá (Lv 19:31; 20:6, 27; Dt 18:11). Aparece regularmente emparejada con yiddeoni (''adivino''), formando una frase establecida para el contacto ilícito con los muertos. La desesperada visita de Saúl a la médium de Endor (1 Sam 28:3-9) ilustra la gravedad de transgredir esta prohibición. En un solo uso llamativo, Job 32:19 emplea la misma palabra para ''odre'': Elihú compara sus palabras contenidas con vino nuevo a punto de reventar su recipiente de cuero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0180', 'spa', 'El Ulai (arameo); río o canal cerca de Susa en Persia, lugar de la visión de Daniel', 'Este sustantivo arameo designa el Ulai, un río o canal situado cerca de la capital persa Susa, donde Daniel recibió visiones proféticas. Daniel 8:2 ubica a Daniel «junto al río Ulai» durante una visión del carnero y el macho cabrío. Daniel 8:3 y 8:6 mencionan «el río» al describir la posición del carnero y la embestida del macho cabrío. El Ulai era probablemente un canal o afluente cercano a Susa, lo que ancla la visión en un lugar geográfico concreto. Este escenario junto al agua evoca otras visiones bíblicas —Ezequiel junto al Quebar, Juan en Patmos— sugiriendo que Dios solía revelarse a profetas exiliados cerca de aguas en tierras extranjeras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0181', 'spa', 'Tizón, leño encendido; trozo de madera parcialmente quemado, usado metafóricamente para los rescatados del desastre', 'Este sustantivo hebreo designa un tizón o leño encendido: un trozo de madera sacado del fuego, carbonizado pero no consumido. Isaías 7:4 desestima la amenaza de Siria e Israel como «dos cabos de tizones humeantes», de aspecto feroz pero casi apagados. Amós 4:11 compara la estrecha escapatoria de Israel con «un tizón arrebatado del incendio», subrayando la misericordia de Dios al preservar un remanente. Zacarías 3:2 emplea la misma imagen para el sumo sacerdote Josué: «¿No es este un tizón arrancado del fuego?», rescatado del exilio y restaurado al servicio a pesar de su indignidad. La metáfora retrata vívidamente a quienes son salvados en el último momento de la destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0182', 'spa', 'El sustantivo אוֹדָה (odah) aparece exclusivamente en el plural constructo אוֹדוֹת / אוֹדֹת con la preposición עַל, formando la preposición compuesta ', 'El sustantivo אוֹדָה (odah) aparece exclusivamente en el plural constructo אוֹדוֹת / אוֹדֹת con la preposición עַל, formando la preposición compuesta ''a causa de'' o ''por motivo de''. Abraham se angustia ''a causa de'' su hijo Ismael (Gn 21:11) y confronta a Abimelec ''por'' el pozo confiscado (Gn 21:25). Los siervos de Isaac informan ''acerca del'' pozo que cavaron (Gn 26:32). Jetro oye todo lo que Dios hizo ''a causa de'' Israel (Ex 18:8). María y Aarón hablan contra Moisés ''por causa de'' la mujer cusita (Nm 12:1). La expresión introduce consistentemente la razón u ocasión de una acción o emoción precedente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0183', 'spa', 'Desear, anhelar o codiciar; abarca desde el deseo neutral hasta la codicia pecaminosa y el anhelo profundo.', 'Desear, anhelar o codiciar; abarca desde el deseo neutral hasta la codicia pecaminosa y el anhelo profundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0185', 'spa', 'Deseo, anhelo, apetencia; un querer intenso o apetito, ya sea natural, regio o divino.', 'El sustantivo femenino ʾavvāh designa un deseo intenso o apetencia, que aparece casi siempre en la construcción ''el deseo del alma''. En Deuteronomio expresa el apetito natural y moralmente neutro por la carne cuando se vive lejos del santuario (Dt 12:15, 20, 21) y el anhelo sincero del levita por servir en el lugar escogido (Dt 18:6). En 1 Samuel 23:20 describe la determinación regia de Saúl por capturar a David. Oseas 10:10 lo aplica a la voluntad deliberada de Dios mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0187', 'spa', 'Uzal; nombre de persona y lugar, hijo de Joctán y región del sur de Arabia (Yemen)', 'Este nombre hebreo designa tanto a una persona como a un lugar. Uzal fue el sexto hijo de Joctán, descendiente de Sem, mencionado en la Tabla de las Naciones (Génesis 10:27; 1 Crónicas 1:21). El nombre también identifica una región o ciudad del sur de Arabia, asociada con la antigua capital de Yemen. Ezequiel 27:19 menciona a Uzal (según enmienda del texto masorético) como socio comercial de Tiro, proveedor de hierro labrado, casia y cálamo, bienes de lujo procedentes de Arabia. El nombre conecta con las redes comerciales de la península arábiga que llevaban especias, metales y aromáticos al mundo mediterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0188', 'spa', '¡Ay! — exclamación apasionada de dolor, desesperación o denuncia profética, que frecuentemente introduce oráculos de juicio.', '¡Ay! — exclamación apasionada de dolor, desesperación o denuncia profética, que frecuentemente introduce oráculos de juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0191', 'spa', 'Necio, insensato — persona moralmente obtusa que desprecia la sabiduría y la disciplina.', 'Necio, insensato — persona moralmente obtusa que desprecia la sabiduría y la disciplina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0192', 'spa', 'Evil-merodac; nombre propio de un rey babilónico, hijo y sucesor de Nabucodonosor', 'Este nombre hebreo designa a Evil-merodac (en babilónico Awel-Marduk, «hombre de Marduk»), rey de Babilonia que sucedió a su padre Nabucodonosor en el 562 a.C. Su breve reinado (562-560 a.C.) se destaca en las Escrituras por un acto significativo: liberó al rey Joaquín de Judá de la prisión, le concedió un puesto de honor y le proveyó sustento el resto de su vida (2 Reyes 25:27; Jeremías 52:31). Esta clemencia real hacia un rey judío cautivo se narra dos veces, subrayando su importancia. Ofreció esperanza a los exiliados de que su suerte podía cambiar. El propio reinado de Evil-merodac fue corto; fue asesinado por su cuñado Neriglisar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0194', 'spa', 'Quizás, tal vez — adverbio que expresa posibilidad esperanzada, duda ansiosa o suposición condicional', 'Quizás, tal vez — adverbio que expresa posibilidad esperanzada, duda ansiosa o suposición condicional');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0197', 'spa', 'Pórtico, vestíbulo, atrio; la sala de entrada cubierta de un templo o palacio', 'Pórtico, vestíbulo, atrio; la sala de entrada cubierta de un templo o palacio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0198', 'spa', 'Ulam; nombre propio masculino que llevan dos hombres en las genealogías de Crónicas.', 'Nombre propio masculino que quizá significa ''pórtico'' o ''vestíbulo'', llevado por dos personajes en los registros genealógicos de Crónicas. El primer Ulam es hijo de Seres en la línea de Manasés (1 Cr 7:16-17). El segundo es un descendiente benjaminita de Saúl cuyos hijos fueron guerreros valientes y prolíficos arqueros, sumando 150 hijos y nietos (1 Cr 8:39-40). El nombre se translitéra de manera uniforme en los distintos idiomas: tanto el español como el inglés y el francés lo rinden como ''Ulam'' u ''Oulam''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0199', 'spa', 'Pero en verdad, sin embargo, ciertamente: conjunción adversativo-aseverativa fuerte que introduce un contraste enfático. Esta conjunción (אוּלָם) intr', 'Pero en verdad, sin embargo, ciertamente: conjunción adversativo-aseverativa fuerte que introduce un contraste enfático. Esta conjunción (אוּלָם) introduce un giro brusco en el argumento, frecuentemente traducida como ''pero en verdad'' o ''sin embargo''. Aparece con mayor frecuencia con waw (וְאוּלָם), fortaleciendo el contraste. Cuando Dios le dice a Faraón ''pero en verdad por esta causa te he levantado'' (Éx 9:16), la partícula subraya la soberanía divina que prevalece sobre la expectativa humana. En Job marca las réplicas decisivas del que sufre: ''pero en cuanto a mí, yo buscaría a Dios'' (Job 5:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0200', 'spa', 'Necedad, insensatez; estupidez moral e intelectual característica del necio en la literatura sapiencial.', 'Necedad, insensatez; estupidez moral e intelectual característica del necio en la literatura sapiencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0201', 'spa', 'Omar; nombre propio que significa «elocuente» u «orador», descendiente de Esaú', 'Este nombre propio hebreo designa a Omar, nieto de Esaú a través de su hijo Elifaz. El nombre posiblemente significa «elocuente» u «orador». Omar aparece en la genealogía de Esaú en Génesis 36:11 y 15, enumerado entre los jefes de Edom, y nuevamente en 1 Crónicas 1:36. Como parte de las familias dirigentes de Edom, Omar representa el cumplimiento de la promesa de Dios de que Esaú también llegaría a ser una gran nación, aunque no la nación de la promesa del pacto. Las genealogías de Edom muestran la providencia de Dios extendiéndose incluso a quienes estaban fuera de la línea directa de Abraham, Isaac y Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0202', 'spa', 'Vigor, fuerza viril, vitalidad; por extension, riqueza, sustancia o recursos materiales. Cuando Jacob bendice a Rubén como ''las primicias de mi vigor''', 'Vigor, fuerza viril, vitalidad; por extension, riqueza, sustancia o recursos materiales. Cuando Jacob bendice a Rubén como ''las primicias de mi vigor'' (Gn 49:3), la palabra אוֹן apunta al poder procreador, la fuerza vital de un hombre en su plenitud. Isaías 40:26 aplica el mismo término al poder cósmico inagotable de Dios, mientras que Isaías 40:29 contrasta a quienes están ''sin fuerza''. Un sentido secundario emerge en la literatura sapiencial y profética, donde el vigor se convierte en riqueza material: Job 20:10 describe a los hijos del malvado devolviendo ''su riqueza'', y Oseas 12:8 registra a Efraín jactándose: ''He hallado riquezas para mí''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0204', 'spa', 'On; nombre propio de una ciudad egipcia, centro de culto al sol, conocida como Heliópolis', 'Este nombre hebreo designa On, una antigua ciudad egipcia (en egipcio ''Iunu'', en griego ''Heliópolis'', que significa ''ciudad del sol''). Ubicada cerca de la actual El Cairo, en la ribera oriental del Nilo, On era un importante centro religioso dedicado al culto del dios solar Ra. Génesis 41:45 y 41:50 identifican a Potifera, suegro de José, como ''sacerdote de On'', y Génesis 46:20 confirma que los hijos de José nacieron de Asenat, hija de este sacerdote. Ezequiel 30:17 profetiza juicio sobre ''los jóvenes de Avén [On]'', condenando la idolatría allí centrada. On representa así la religión y cultura egipcias en las que José se integró por matrimonio, un detalle que resalta la providencia de Dios al exaltar a José incluso dentro de las estructuras paganas de Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0205', 'spa', 'Iniquidad, aflicción, vanidad; abarca desde la maldad y sus consecuencias hasta la vacuidad, el duelo y la nada.', 'אָוֶן es una de esas palabras hebreas cuyo campo semántico revela toda una teología: iniquidad, aflicción, maldad y nada no son categorías separadas, sino puntos de un mismo continuo. Lo que comienza como ''iniquidad'' moral inevitablemente produce ''aflicción'' para otros y termina colapsando en ''vacuidad.'' El oráculo de Balaam declara que Dios ''no ha visto אָוֶן en Jacob'' (Nm 23:21), donde el paralelismo con עָמָל (miseria, fatiga) muestra cuán estrechamente se entrelazan la maldad y sus dolorosas consecuencias. Los profetas explotan esta fusión magistralmente: Oseas renombra Bet-el (''casa de Dios'') como Bet-aven (''casa de nada''), e Isaías 41:29 declara que los ídolos son אָוֶן — simultáneamente perversos, inútiles y vacíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0207', 'spa', 'Ono -- ciudad benjaminita al noroeste de Lida, asociada con la llanura del mismo nombre', 'Ono era una ciudad en el territorio de Benjamín, identificada con la moderna Kefr Ana, al noroeste de Lida (Lod). Sus cinco apariciones abarcan desde las genealogías del Cronista hasta la comunidad postexílica. Aparece por primera vez como ciudad edificada (o reconstruida) por el benjaminita Semed (1 Cr 8:12), luego en los censos de los exiliados que regresaron junto a Lod (Esd 2:33; Neh 7:37), en la lista de repoblación (Neh 11:35), y notablemente en Nehemías 6:2, donde Sanbalat y Gesem proponen reunirse ''en la llanura de Ono'', invitación que Nehemías sabiamente rechaza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0208', 'spa', 'Onam; nombre propio de un jefe horita y de un cabeza de clan de Judá', 'Nombre propio masculino que probablemente significa «vigoroso» o «fuerte», llevado por dos personajes del Antiguo Testamento. El primer Onam es hijo de Sobal, uno de los jefes horitas de Seír, mencionado en Génesis 36:23 y en la genealogía paralela de 1 Crónicas 1:40. El segundo es hijo de Jerameel en la tribu de Judá (1 Cr 2:26, 28). El nombre se conserva de forma consistente en las traducciones a distintos idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0209', 'spa', 'Onán — segundo hijo de Judá, cuyo nombre significa ''vigoroso'' o ''fuerte''.', 'Onán fue el segundo hijo de Judá y su esposa cananea, conocido principalmente por el relato de Génesis 38, donde se negó a cumplir el deber del matrimonio por levirato con la viuda de su hermano Er. Su nombre, que significa ''vigoroso'', aparece ocho veces en Génesis, Números y 1 Crónicas. La evidencia multilingüe —hindi ओनान, español Onán, francés y alemán Onan— muestra una transliteración uniforme, como es esperable para un nombre propio sin ambigüedad semántica en contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0211', 'spa', 'Ofir — una tierra lejana célebre por su oro, alcanzada por las expediciones marítimas de Salomón. Ofir aparece 13 veces en la Biblia hebrea como nombr', 'Ofir — una tierra lejana célebre por su oro, alcanzada por las expediciones marítimas de Salomón. Ofir aparece 13 veces en la Biblia hebrea como nombre personal (un descendiente de Joctán en Gn 10:29) y, con mucha mayor prominencia, como una legendaria tierra de oro. La flota de Salomón zarpó de Ezión-Guéber hacia Ofir y regresó con oro, madera de sándalo y piedras preciosas (1 R 9:28; 10:11). Su ubicación exacta sigue siendo uno de los grandes enigmas geográficos de la Biblia, con candidatos que van desde el sur de Arabia hasta el este de África o el oeste de la India. En el uso poético, ''oro de Ofir'' se convirtió en sinónimo de la más alta calidad (Sal 45:9; Job 28:16; Is 13:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0212', 'spa', 'Rueda — componente circular giratorio de carros, fuentes del templo, trillos y la visión de Ezequiel', 'Rueda — componente circular giratorio de carros, fuentes del templo, trillos y la visión de Ezequiel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0213', 'spa', 'Apresurarse, presionar o urgir; también ser estrecho o angosto, describiendo un espacio constreñido. Verbo con dos polos semánticos distintos. En la m', 'Apresurarse, presionar o urgir; también ser estrecho o angosto, describiendo un espacio constreñido. Verbo con dos polos semánticos distintos. En la mayoría de sus apariciones transmite urgencia y prisa: los ángeles apremian a Lot para que huya de Sodoma (Gn 19:15), los capataces egipcios presionan a los israelitas (Éx 5:13), y Proverbios advierte repetidamente contra los pies y las palabras apresuradas (19:2; 21:5; 28:20; 29:20). Sin embargo, en Josué 17:15, la misma raíz describe constricción espacial: «la región montañosa de Efraín es demasiado estrecha para vosotros», un significado confirmado por el árabe daqa (''ser estrecho''). La literatura sapiencial emplea el sentido de prisa con particular fuerza: «todo el que se apresura, solo llegará a la pobreza» (Pr 21:5), un proverbio cuyas traducciones multilingües enfatizan consistentemente la temeridad más que la mera velocidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0214', 'spa', 'Tesoro, tesorería, almacén; riqueza almacenada, edificio para objetos valiosos o granero para provisiones y reservas cósmicas.', 'El hebreo אוֹצָר abarca tanto el continente como el contenido — el edificio del tesoro y la riqueza que alberga. Los depósitos reales y del templo (Jos 6:19, 1 R 7:51) son el referente más frecuente. La palabra adquiere un giro cósmico en pasajes como Sal 135:7 y Job 38:22, donde Dios tiene ''depósitos'' de viento, granizo y nieve — una vívida metáfora que trata las fuerzas naturales como provisiones divinas guardadas en reserva. Proverbios la emplea figuradamente para las recompensas de la sabiduría (Pr 8:21) y advierte contra los tesoros mal habidos (Pr 10:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0215', 'spa', 'Ser o hacerse luz, brillar; dar luz, iluminar; hacer resplandecer el rostro (mostrar favor); encender una lámpara', 'Ser o hacerse luz, brillar; dar luz, iluminar; hacer resplandecer el rostro (mostrar favor); encender una lámpara');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0216', 'spa', 'Luz: luz del día, alba, luz solar; metafóricamente vida, favor divino, salvación; también relámpago; las lumbreras.', 'אוֹר es el sustantivo primario de la Biblia hebrea para la luz en toda su riqueza física y metafórica. La primera palabra creadora de Dios la llama a la existencia —''Sea la luz'' (Gn 1:3)— y desde ese momento irradia a través de las Escrituras como fenómeno concreto y símbolo profundo. Físicamente designa la luz del día (Gn 1:4-5), el alba (Jue 16:2; 1 S 14:36) y la luz de los astros (Is 30:26). Metafóricamente su alcance es extraordinario: luz como vida misma (Job 3:20; Sal 56:13), como favor divino y salvación (''YHWH es mi luz,'' Sal 27:1), como torá y guía moral (Pr 6:23; Is 2:5) y como gloria escatológica (Is 60:1, 19-20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0217a', 'spa', 'Fuego, llama o luz de fuego; se usa para fuego literal y figuradamente para el juicio divino', 'Sustantivo poético que designa el fuego en cuanto llama visible y luz radiante, más que simple combustión. Isaías lo emplea con fuerza: a los malvados se les dice ''caminad a la luz de vuestro fuego'' (Is 50:11), mientras que el fuego de Babilonia no da calor ni luz junto a la cual sentarse (Is 47:14). Las cinco apariciones se sitúan en contextos proféticos donde el fuego sirve como vehículo de advertencia o juicio divino. Las traducciones en español oscilan entre ''fuego'', ''lumbre'' y ''luz'', reflejando la doble cualidad de llama y resplandor que distingue a este vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0218b', 'spa', 'Ur (de los caldeos); la antigua ciudad mesopotámica, tierra natal de la familia de Abraham', 'La célebre ciudad mesopotámica de Ur de los caldeos, identificada con la actual Muqayyar en el sur de Irak, antiguo centro de culto al dios lunar. Las cuatro referencias bíblicas presentan a Ur como el punto de origen de la familia de Abraham: Taré partió de Ur con Abram (Gn 11:28, 31), y Dios le recuerda después a Abraham que lo sacó de Ur de los caldeos (Gn 15:7; Neh 9:7). Este topónimo ancla toda la narrativa patriarcal del llamado divino y la migración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0219a', 'spa', 'Luz; iluminación, resplandor, o la luz del gozo y la vida (poético, hebreo tardío)', 'Este sustantivo hebreo denota luz, empleado de manera poética en textos bíblicos tardíos. Aparece en contextos que celebran la luz como símbolo de gozo, vida y bendición divina. Ester 8:16 declara: «Los judíos tuvieron luz, alegría, gozo y honra», donde la luz se equipara con la alegría en la celebración de la liberación. Salmo 139:12 afirma la omnisciencia de Dios: «Aun las tinieblas no encubren de ti; la noche resplandece como el día; lo mismo te son las tinieblas que la luz.» Isaías 26:19 habla de resurrección: «Tus muertos vivirán... despertad y cantad, moradores del polvo, porque tu rocío es como rocío de luces.» El término capta el poder vivificante y gozoso de la luz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0221', 'spa', 'Uri — nombre propio hebreo que significa ''ardiente'', llevado por tres hombres distintos en el Antiguo Testamento.', 'Uri (que significa ''ardiente'', posiblemente una forma abreviada de Urías) es un nombre llevado por al menos tres individuos en las Escrituras: el padre de Bezaleel, artesano principal del tabernáculo (Éx 31:2; 35:30; 38:22); un portero del templo en tiempos de Esdras (Esd 10:24); y el padre de uno de los gobernadores de distrito de Salomón (1 R 4:19). A pesar de referirse a personas distintas, las traducciones lo rinden de manera consistente como una simple transliteración —en español e inglés ''Uri'', en francés y alemán lo mismo— lo que refleja su fonología transparente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0222', 'spa', 'Uriel; nombre levítico que significa «llama de Dios» o «mi luz es Dios»', 'Nombre propio masculino compuesto de אוּר (luz, llama) y אֵל (Dios), con el significado de «llama de Dios» o «mi luz es Dios». Uriel aparece como jefe de los levitas coatitas en tiempos de David, encargado de trasladar el arca a Jerusalén (1 Cr 6:24; 15:5, 11). También figura como abuelo materno del rey Abías de Judá (2 Cr 13:2). Este nombre teofórico expresa con belleza la dependencia de Dios como luz que guía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0223a', 'spa', 'Urías / Uriyahu — nombre teofórico (''YHWH es mi luz'') portado por un guerrero hitita, un sacerdote y otros', 'Urías / Uriyahu — nombre teofórico (''YHWH es mi luz'') portado por un guerrero hitita, un sacerdote y otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0224', 'spa', 'Urim; los objetos sagrados de sorteo guardados en el pectoral del sumo sacerdote para obtener dirección divina.', 'Los Urim (plural de intensidad, posiblemente ''luces'' o ''maldiciones'') eran objetos sagrados colocados dentro del pectoral de juicio del sumo sacerdote, empleados para consultar la voluntad de Dios en decisiones cruciales. Aparecen junto con los Tumim como sistema oracular emparejado (Éx 28:30; Lv 8:8). Moisés encarga a Josué buscar dirección ''por el juicio de los Urim'' mediante el sacerdote Eleazar (Nm 27:21). En tiempos de Saúl, los Urim habían enmudecido: Dios ''no le respondió, ni por sueños, ni por Urim, ni por profetas'' (1 S 28:6). Su función era clara: consulta divina de tipo sí o no.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0225', 'spa', 'Consentir, aceptar; usado solo en Nifal, expresa asentimiento voluntario a una propuesta', 'Verbo que aparece exclusivamente en la conjugación Nifal y transmite la idea de dar consentimiento o aceptar los términos propuestos por otra parte. Sus cuatro apariciones se agrupan en dos episodios de negociación. En Génesis 34:15, 22-23, los hijos de Jacob ponen la circuncisión como condición para consentir en el matrimonio mixto con los siquemitas, un tenso intercambio diplomático. En 2 Reyes 12:8, los sacerdotes aceptan no tomar plata del pueblo, cediendo autoridad sobre las reparaciones del templo. La palabra siempre implica un asentimiento deliberado y razonado, no una aquiescencia pasiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0226', 'spa', 'Senal, portento milagroso, marca de pacto o estandarte tribal; un indicador visible que transmite significado divino o identidad colectiva.', 'Senal, portento milagroso, marca de pacto o estandarte tribal; un indicador visible que transmite significado divino o identidad colectiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0227a', 'spa', 'Entonces — adverbio temporal que señala un momento en el pasado o el futuro, a menudo marcando el inicio de una nueva acción.', 'אָז es un adverbio hebreo compacto cuyas dos letras portan un peso retórico sorprendente. Ancla la narrativa a un momento específico —''entonces los hombres comenzaron a invocar el nombre de YHWH'' (Gn 4:26)— y en la poesía profética salta hacia una transformación futura: ''entonces los ojos de los ciegos serán abiertos'' (Is 35:5). Un rasgo sintáctico distintivo es su combinación con un verbo imperfecto para narrar eventos pasados, una construcción que señala inicio o comienzo dramático (Ex 15:1, ''entonces cantó Moisés''). La palabra también aparece en el compuesto מֵאָז (''desde entonces, de antiguo'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0227b', 'spa', 'Desde antiguo, desde tiempos remotos; también desde que, desde el momento en que, marcando un punto de partida temporal en el pasado. Este adverbio-pr', 'Desde antiguo, desde tiempos remotos; también desde que, desde el momento en que, marcando un punto de partida temporal en el pasado. Este adverbio-preposición compuesto (מִן + אָז, ''desde entonces'') ancla los eventos en el tiempo pasado, ya sea remontándose a una antigüedad indefinida o señalando un momento específico. Cuando el salmista declara el trono de Dios establecido ''desde antiguo'' (Sal 93:2), o la Sabiduría habla de haber sido establecida ''desde la eternidad'' (Pr 8:22), מֵאָז evoca permanencia primordial. Pero en contextos narrativos como Génesis 39:5 y Éxodo 5:23, funciona como conjunción: ''desde que vine a Faraón'', marcando el inicio preciso de una situación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0228', 'spa', 'Calentar, ser calentado (arameo); hacer arder, especialmente un horno', 'Este verbo arameo significa calentar o ser calentado, y aparece únicamente en Daniel 3 dentro del relato del horno de fuego. Daniel 3:19 describe la furia de Nabucodonosor cuando Sadrac, Mesac y Abed-nego se niegan a adorar su imagen: ordena que el horno sea calentado siete veces más de lo acostumbrado. Daniel 3:22 señala el resultado letal: «Como la orden del rey era apremiante y el horno estaba extremadamente caliente, la llama del fuego mató a aquellos hombres que habían llevado a Sadrac, Mesac y Abed-nego.» El verbo subraya la intensidad de la ejecución prevista y, de modo irónico, la magnitud de la liberación obrada por Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0231', 'spa', 'Hisopo — una pequeña hierba arbustiva utilizada en los ritos de purificación israelitas para la aspersión de sangre y agua lustral. El sustantivo אֵזו', 'Hisopo — una pequeña hierba arbustiva utilizada en los ritos de purificación israelitas para la aspersión de sangre y agua lustral. El sustantivo אֵזוֹב (ezov) designa el hisopo, una pequeña planta aromática empleada como instrumento de aspersión ritual en las ceremonias de purificación de Israel. En la primera Pascua, los israelitas mojaron manojos de hisopo en sangre de cordero para marcar los dinteles de sus puertas (Éx 12:22). En la purificación de leprosos, el hisopo se ata con madera de cedro e hilo escarlata y se sumerge en sangre sacrificial (Lv 14:4, 6, 49, 51-52). El rito de la vaca roja igualmente emplea hisopo (Nm 19:6, 18). La súplica del salmista «purifícame con hisopo y seré limpio» (Sal 51:9) interioriza el ritual como metáfora espiritual. La identificación botánica sigue siendo debatida: Origanum syriacum (orégano sirio) es el principal candidato. El español ''hisopo'' y el francés ''hysope'' derivan de la misma raíz semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0232', 'spa', 'Cinturón, cinto, faja — prenda que se lleva alrededor de la cintura, hecha de cuero o lino. Designa un paño o banda que se ata a la cintura y funciona', 'Cinturón, cinto, faja — prenda que se lleva alrededor de la cintura, hecha de cuero o lino. Designa un paño o banda que se ata a la cintura y funciona como prenda básica o atadura. El término hebreo אֵזוֹר aparece en varios contextos bíblicos vívidos: el cinto de cuero de Elías lo distingue como profeta del desierto (2 R 1:8), mientras que el cinturón de lino de Jeremías se convierte en una parábola escenificada — usado, escondido junto al Éufrates y recuperado arruinado — que simboliza el vínculo íntimo de Israel con Dios, ahora corrompido (Jer 13:1-11). Isaías describe guerreros asirios cuyos cinturones jamás se aflojan (Is 5:27) y al rey mesiánico ceñido de justicia y fidelidad (Is 11:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0233', 'spa', 'Entonces, en ese caso; partícula temporal o lógica que indica consecuencia', 'Este adverbio hebreo significa «entonces» o «en ese caso», marcando secuencia temporal o consecuencia lógica. Aparece tres veces en Salmo 124:3-5, en un cántico climático de liberación. El salmista construye una hipótesis: «Si el SEÑOR no hubiera estado de nuestra parte... entonces nos habrían tragado vivos... entonces nos habrían inundado las aguas... entonces las aguas impetuosas habrían pasado sobre nuestra alma.» Cada «entonces» introduce una consecuencia que habría ocurrido sin la intervención de Dios. La repetición intensifica el efecto, mostrando cuán cerca estuvo Israel de la destrucción y cuán completamente Dios los libró. Este adverbio es dialectal, emparentado con el más común אָז.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0234', 'spa', 'Porción memorial de la ofrenda de cereal quemada sobre el altar como recordatorio ante YHWH.', 'Derivado de la raíz z-k-r (''recordar''), este sustantivo femenino designa específicamente el puñado de harina, aceite e incienso tomado de una ofrenda de cereal (minhah) y quemado sobre el altar como ''recordatorio'' simbólico ante Dios. Aparece exclusivamente en la legislación sacerdotal (Levítico 2, 5, 6; Números 5), siempre en estrecha relación con ʾishsheh (ofrenda encendida). El término español ''porción memorial'' capta la doble noción de una porción que también conmemora: un signo físico que asciende como humo para presentar la devoción del oferente ante el Señor.');